PRAGMA foreign_keys = ON;
ALTER TABLE pl_units ADD COLUMN cefr_level TEXT NOT NULL DEFAULT 'A1';
ALTER TABLE pl_learning_items ADD COLUMN cefr_level TEXT NOT NULL DEFAULT 'A1';
ALTER TABLE pl_learning_items ADD COLUMN skills_json TEXT NOT NULL DEFAULT '["spoken_interaction"]';
ALTER TABLE pl_learning_items ADD COLUMN scene TEXT NOT NULL DEFAULT 'general';
ALTER TABLE pl_learning_items ADD COLUMN register TEXT NOT NULL DEFAULT 'neutral';
ALTER TABLE pl_learning_items ADD COLUMN speaker_gender TEXT NOT NULL DEFAULT 'any';
ALTER TABLE pl_learning_items ADD COLUMN dialogue_role TEXT NOT NULL DEFAULT 'learner';
ALTER TABLE pl_learning_items ADD COLUMN source_kind TEXT NOT NULL DEFAULT 'independent';
UPDATE pl_units SET cefr_level = 'A1' WHERE cefr_level = 'A1';
UPDATE pl_learning_items SET cefr_level = 'A1', skills_json = '["spoken_production","spoken_interaction"]', scene = topic, register = 'neutral', speaker_gender = 'any', dialogue_role = 'learner', source_kind = 'independent' WHERE content_version LIKE 'a1-%';
INSERT OR IGNORE INTO pl_tracks (id, code, title, cefr, content_version, status, created_at) VALUES ('track-a2', 'A2', 'Polski Loop A2', 'A2', 'a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT OR IGNORE INTO pl_content_versions (version, track_id, status, notes, created_at) VALUES ('a2-2026.1', 'track-a2', 'published', 'A2生活特化教材。独自作成、各lesson 6表現・14段階step。', strftime('%Y-%m-%dT%H:%M:%fZ','now'));
CREATE TABLE IF NOT EXISTS pl_voice_missions (id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES pl_units(id), lesson_id TEXT NOT NULL UNIQUE REFERENCES pl_lessons(id), title TEXT NOT NULL, scenario TEXT NOT NULL, learner_role TEXT NOT NULL, partner_role TEXT NOT NULL, objective TEXT NOT NULL, learner_item_ids_json TEXT NOT NULL, partner_item_ids_json TEXT NOT NULL, required_item_ids_json TEXT NOT NULL, partner_behavior TEXT NOT NULL, difficulty_level TEXT NOT NULL CHECK (difficulty_level IN ('A1','A2')), ending_condition TEXT NOT NULL, feedback_format TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'published' CHECK (status IN ('draft','published','retired')), created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pl_voice_attempts (id TEXT PRIMARY KEY, idempotency_key TEXT NOT NULL UNIQUE, profile_id TEXT NOT NULL REFERENCES pl_profiles(id), mission_id TEXT NOT NULL REFERENCES pl_voice_missions(id), session_id TEXT REFERENCES pl_study_sessions(id), heard INTEGER NOT NULL CHECK (heard IN (0,1)), replied INTEGER NOT NULL CHECK (replied IN (0,1)), asked_back INTEGER NOT NULL CHECK (asked_back IN (0,1)), rephrased INTEGER NOT NULL CHECK (rephrased IN (0,1)), confidence INTEGER NOT NULL CHECK (confidence BETWEEN 1 AND 5), notes TEXT NOT NULL DEFAULT '', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pl_cando_items (id TEXT PRIMARY KEY, unit_id TEXT NOT NULL REFERENCES pl_units(id), code TEXT NOT NULL UNIQUE, cefr_level TEXT NOT NULL CHECK (cefr_level IN ('A1','A2')), skill TEXT NOT NULL CHECK (skill IN ('listening','spoken_interaction','spoken_production')), statement_ja TEXT NOT NULL, statement_pl TEXT NOT NULL, evidence_rule TEXT NOT NULL, sort_order INTEGER NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS pl_cando_progress (profile_id TEXT NOT NULL REFERENCES pl_profiles(id), cando_id TEXT NOT NULL REFERENCES pl_cando_items(id), status TEXT NOT NULL DEFAULT 'not_started' CHECK (status IN ('not_started','practicing','self_assessed','evidenced')), self_rating INTEGER CHECK (self_rating BETWEEN 1 AND 5), evidence_notes TEXT NOT NULL DEFAULT '', last_mission_attempt_id TEXT REFERENCES pl_voice_attempts(id), updated_at TEXT NOT NULL, PRIMARY KEY (profile_id, cando_id));
ALTER TABLE pl_chatgpt_prompts ADD COLUMN mission_id TEXT REFERENCES pl_voice_missions(id);
CREATE INDEX IF NOT EXISTS idx_pl_voice_attempts_profile_created ON pl_voice_attempts(profile_id, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_pl_cando_unit_order ON pl_cando_items(unit_id, sort_order);
INSERT OR IGNORE INTO pl_units (id, track_id, unit_number, title_ja, title_pl, description, status, cefr_level) VALUES ('a2-unit-1', 'track-a2', 1, '自分と人間関係', 'Ja i relacje', '自己紹介を広げ、家族・性格・誘い・気持ちを短いやり取りで伝えます。', 'published', 'A2');
INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u1-l1', 'a2-unit-1', 1, '仕事まで含めて自己紹介', 'Przedstawiam się szerzej', '現在形、z + 生格、zajmować się + 造格を使って、出身・居住・仕事を一続きで話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l1-i01', 'sentence', 'Mam na imię Marek, ale możesz mówić do mnie Marek.', '私の名前はマレクです。マレクと呼んでください。', 'My name is Marek, but you can call me Marek.', '現在形、z + 生格、zajmować się + 造格を使って、出身・居住・仕事を一続きで話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'introduction', '["cefr:a2","scene:introduction","grammar:present-tense","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mam na imię Marek, ale możesz mówić do mnie Marek","Mam na imię Marek, ale możesz mówić do mnie Marek."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'introduction', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l1-i02', 'sentence', 'Skąd dokładnie jesteś?', '具体的にはどこの出身ですか？', 'Where exactly are you from?', '現在形、z + 生格、zajmować się + 造格を使って、出身・居住・仕事を一続きで話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'introduction', '["cefr:a2","scene:introduction","grammar:present-tense","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Skąd dokładnie jesteś","Skąd dokładnie jesteś?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'introduction', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l1-i03', 'sentence', 'Pochodzę z Japonii, ale od dwóch lat mieszkam w Polsce.', '日本出身ですが、2年前からポーランドに住んでいます。', 'I come from Japan, but I have lived in Poland for two years.', '現在形、z + 生格、zajmować się + 造格を使って、出身・居住・仕事を一続きで話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'introduction', '["cefr:a2","scene:introduction","grammar:present-tense","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Pochodzę z Japonii, ale od dwóch lat mieszkam w Polsce","Pochodzę z Japonii, ale od dwóch lat mieszkam w Polsce."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'introduction', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l1-i04', 'sentence', 'A czym zajmujesz się na co dzień?', '普段は何をしていますか？', 'And what do you do day to day?', '現在形、z + 生格、zajmować się + 造格を使って、出身・居住・仕事を一続きで話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'introduction', '["cefr:a2","scene:introduction","grammar:present-tense","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["A czym zajmujesz się na co dzień","A czym zajmujesz się na co dzień?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'introduction', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l1-i05', 'sentence', 'Pracuję zdalnie jako projektant.', 'リモートでデザイナーとして働いています。', 'I work remotely as a designer.', '現在形、z + 生格、zajmować się + 造格を使って、出身・居住・仕事を一続きで話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'introduction', '["cefr:a2","scene:introduction","grammar:present-tense","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Pracuję zdalnie jako projektant","Pracuję zdalnie jako projektant."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'introduction', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l1-i06', 'sentence', 'To musi być ciekawe. Co lubisz robić po pracy?', 'それは面白そうですね。仕事の後は何をするのが好きですか？', 'That must be interesting. What do you like doing after work?', '現在形、z + 生格、zajmować się + 造格を使って、出身・居住・仕事を一続きで話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'introduction', '["cefr:a2","scene:introduction","grammar:present-tense","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["To musi być ciekawe. Co lubisz robić po pracy","To musi być ciekawe. Co lubisz robić po pracy?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'introduction', 'informal', 'male', 'partner', 'independent');
