INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u1-l1-s13', 'a2-u1-l1', 13, 'input', 'a2-u1-l1-i05', '「リモートでデザイナーとして働いています。」をポーランド語で言いましょう。', '現在形、z + 生格、zajmować się + 造格を使って、出身・居住・仕事を一続きで話します。', '[]', 'free_input', 'meaning_to_polish', 'Pracuję zdalnie jako projektant.', '', '', '', '[]', 2, '手がかりなしで思い出す');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u1-l1-s14', 'a2-u1-l1', 14, 'input', 'a2-u1-l1-i06', '「それは面白そうですね。仕事の後は何をするのが好きですか？」をポーランド語で言いましょう。', '現在形、z + 生格、zajmować się + 造格を使って、出身・居住・仕事を一続きで話します。', '[]', 'free_input', 'meaning_to_polish', 'To musi być ciekawe. Co lubisz robić po pracy?', '', '', '', '[]', 2, '手がかりなしで思い出す');
INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u1-l2', 'a2-unit-1', 2, '家族について話す', 'Moja rodzina', '人数の表現、mieć、dzwonić do + 生格を使って、家族構成と連絡の頻度を話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l2-i01', 'sentence', 'Mam starszą siostrę i młodszego brata.', '姉と弟がいます。', 'I have an older sister and a younger brother.', '人数の表現、mieć、dzwonić do + 生格を使って、家族構成と連絡の頻度を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'family', '["cefr:a2","scene:family","grammar:accusative-genitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mam starszą siostrę i młodszego brata","Mam starszą siostrę i młodszego brata."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'family', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l2-i02', 'sentence', 'Ile osób liczy twoja rodzina?', 'あなたの家族は何人ですか？', 'How many people are in your family?', '人数の表現、mieć、dzwonić do + 生格を使って、家族構成と連絡の頻度を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'family', '["cefr:a2","scene:family","grammar:accusative-genitive","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Ile osób liczy twoja rodzina","Ile osób liczy twoja rodzina?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'family', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l2-i03', 'sentence', 'Moja siostra mieszka w Gdańsku, a brat studiuje w Krakowie.', '姉はグダニスクに、弟はクラクフで勉強しています。', 'My sister lives in Gdańsk, and my brother studies in Kraków.', '人数の表現、mieć、dzwonić do + 生格を使って、家族構成と連絡の頻度を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'family', '["cefr:a2","scene:family","grammar:accusative-genitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Moja siostra mieszka w Gdańsku, a brat studiuje w Krakowie","Moja siostra mieszka w Gdańsku, a brat studiuje w Krakowie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'family', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l2-i04', 'sentence', 'Czy często odwiedzasz rodzinę?', '家族をよく訪ねますか？', 'Do you often visit your family?', '人数の表現、mieć、dzwonić do + 生格を使って、家族構成と連絡の頻度を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'family', '["cefr:a2","scene:family","grammar:accusative-genitive","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy często odwiedzasz rodzinę","Czy często odwiedzasz rodzinę?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'family', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l2-i05', 'sentence', 'W weekendy dzwonię do rodziców.', '週末には両親に電話します。', 'At weekends I call my parents.', '人数の表現、mieć、dzwonić do + 生格を使って、家族構成と連絡の頻度を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'family', '["cefr:a2","scene:family","grammar:accusative-genitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W weekendy dzwonię do rodziców","W weekendy dzwonię do rodziców."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'family', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l2-i06', 'sentence', 'Rozumiem, rodzina jest dla ciebie ważna.', 'なるほど、家族はあなたにとって大切なのですね。', 'I see, family is important to you.', '人数の表現、mieć、dzwonić do + 生格を使って、家族構成と連絡の頻度を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'family', '["cefr:a2","scene:family","grammar:accusative-genitive","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Rozumiem, rodzina jest dla ciebie ważna","Rozumiem, rodzina jest dla ciebie ważna."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'family', 'informal', 'male', 'partner', 'independent');
