INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u1-l3', 'a2-unit-1', 3, '人柄と外見を説明する', 'Jaki on jest?', '形容詞の性・数の一致と、bardziej ... niż ... の比較を使って人を説明します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l3-i01', 'sentence', 'Mój partner jest spokojny i cierpliwy.', '私のパートナーは穏やかで我慢強いです。', 'My partner is calm and patient.', '形容詞の性・数の一致と、bardziej ... niż ... の比較を使って人を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'relationships', '["cefr:a2","scene:relationships","grammar:adjective-agreement","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mój partner jest spokojny i cierpliwy","Mój partner jest spokojny i cierpliwy."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'relationships', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l3-i02', 'sentence', 'Jaki jest twój najlepszy przyjaciel?', 'あなたの親友はどんな人ですか？', 'What is your best friend like?', '形容詞の性・数の一致と、bardziej ... niż ... の比較を使って人を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'relationships', '["cefr:a2","scene:relationships","grammar:adjective-agreement","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jaki jest twój najlepszy przyjaciel","Jaki jest twój najlepszy przyjaciel?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'relationships', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l3-i03', 'sentence', 'Ma krótkie włosy i zawsze nosi okulary.', 'その人は短い髪で、いつも眼鏡をかけています。', 'He has short hair and always wears glasses.', '形容詞の性・数の一致と、bardziej ... niż ... の比較を使って人を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'relationships', '["cefr:a2","scene:relationships","grammar:adjective-agreement","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Ma krótkie włosy i zawsze nosi okulary","Ma krótkie włosy i zawsze nosi okulary."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'relationships', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l3-i04', 'sentence', 'Czy twoja przyjaciółka jest bardziej podobna do ciebie czy do siostry?', 'あなたの女友達はあなたと姉妹のどちらに似ていますか？', 'Is your female friend more like you or your sister?', '形容詞の性・数の一致と、bardziej ... niż ... の比較を使って人を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'relationships', '["cefr:a2","scene:relationships","grammar:adjective-agreement","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy twoja przyjaciółka jest bardziej podobna do ciebie czy do siostry","Czy twoja przyjaciółka jest bardziej podobna do ciebie czy do siostry?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'relationships', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l3-i05', 'sentence', 'Jestem raczej nieśmiały, ale łatwo nawiązuję rozmowę.', '私はどちらかというと内気ですが、すぐ会話を始められます。', 'I am rather shy, but I easily start a conversation.', '形容詞の性・数の一致と、bardziej ... niż ... の比較を使って人を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'relationships', '["cefr:a2","scene:relationships","grammar:adjective-agreement","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Jestem raczej nieśmiały, ale łatwo nawiązuję rozmowę","Jestem raczej nieśmiały, ale łatwo nawiązuję rozmowę."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'relationships', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l3-i06', 'sentence', 'To brzmi bardzo sympatycznie.', 'それはとても感じがよさそうですね。', 'That sounds very nice.', '形容詞の性・数の一致と、bardziej ... niż ... の比較を使って人を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'relationships', '["cefr:a2","scene:relationships","grammar:adjective-agreement","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["To brzmi bardzo sympatycznie","To brzmi bardzo sympatycznie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'relationships', 'informal', 'male', 'partner', 'independent');
