INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u1-l4', 'a2-unit-1', 4, '誘いと予定を調整する', 'Umawiamy się', 'masz ochotę + 不定詞、może、条件の受け答えで、誘いを受けたり断ったりします。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l4-i01', 'sentence', 'Masz ochotę pójść ze mną na kawę?', '私とコーヒーを飲みに行きませんか？', 'Would you like to go for coffee with me?', 'masz ochotę + 不定詞、może、条件の受け答えで、誘いを受けたり断ったりします。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'social-life', '["cefr:a2","scene:social-life","grammar:conditional-politeness","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Masz ochotę pójść ze mną na kawę","Masz ochotę pójść ze mną na kawę?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'social-life', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l4-i02', 'sentence', 'Chętnie, ale o której?', 'ぜひ、何時ですか？', 'Gladly, but at what time?', 'masz ochotę + 不定詞、może、条件の受け答えで、誘いを受けたり断ったりします。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'social-life', '["cefr:a2","scene:social-life","grammar:conditional-politeness","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Chętnie, ale o której","Chętnie, ale o której?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'social-life', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l4-i03', 'sentence', 'Może spotkamy się w sobotę po południu?', '土曜日の午後に会いませんか？', 'Shall we meet on Saturday afternoon?', 'masz ochotę + 不定詞、może、条件の受け答えで、誘いを受けたり断ったりします。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'social-life', '["cefr:a2","scene:social-life","grammar:conditional-politeness","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Może spotkamy się w sobotę po południu","Może spotkamy się w sobotę po południu?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'social-life', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l4-i04', 'sentence', 'Niestety nie mogę, bo mam już plany.', '残念ですが、もう予定があります。', 'Unfortunately I cannot, because I already have plans.', 'masz ochotę + 不定詞、może、条件の受け答えで、誘いを受けたり断ったりします。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'social-life', '["cefr:a2","scene:social-life","grammar:conditional-politeness","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Niestety nie mogę, bo mam już plany","Niestety nie mogę, bo mam już plany."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'social-life', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l4-i05', 'sentence', 'W takim razie zaproponuję niedzielę.', 'それなら日曜日を提案します。', 'In that case I will suggest Sunday.', 'masz ochotę + 不定詞、może、条件の受け答えで、誘いを受けたり断ったりします。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'social-life', '["cefr:a2","scene:social-life","grammar:conditional-politeness","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W takim razie zaproponuję niedzielę","W takim razie zaproponuję niedzielę."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'social-life', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l4-i06', 'sentence', 'Świetnie, wpiszmy to do kalendarza.', 'いいですね、カレンダーに入れましょう。', 'Great, let us put it in the calendar.', 'masz ochotę + 不定詞、może、条件の受け答えで、誘いを受けたり断ったりします。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'social-life', '["cefr:a2","scene:social-life","grammar:conditional-politeness","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Świetnie, wpiszmy to do kalendarza","Świetnie, wpiszmy to do kalendarza."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'social-life', 'neutral', 'male', 'partner', 'independent');
