INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u1-l5', 'a2-unit-1', 5, '気持ちと困りごとを共有する', 'Jak się czuję', 'martwić się、czuć się、potrzebowaćとbo/żebyを使って、状態と必要な時間を伝えます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l5-i01', 'sentence', 'Trochę się martwię, bo nie znam jeszcze wielu osób.', 'まだ多くの人を知らないので、少し心配です。', 'I am a little worried because I do not know many people yet.', 'martwić się、czuć się、potrzebowaćとbo/żebyを使って、状態と必要な時間を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'feelings', '["cefr:a2","scene:feelings","grammar:reflexive-verbs","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Trochę się martwię, bo nie znam jeszcze wielu osób","Trochę się martwię, bo nie znam jeszcze wielu osób."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'feelings', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l5-i02', 'sentence', 'Co się stało? Chcesz o tym porozmawiać?', 'どうしたのですか？そのことを話したいですか？', 'What happened? Do you want to talk about it?', 'martwić się、czuć się、potrzebowaćとbo/żebyを使って、状態と必要な時間を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'feelings', '["cefr:a2","scene:feelings","grammar:reflexive-verbs","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Co się stało? Chcesz o tym porozmawiać","Co się stało? Chcesz o tym porozmawiać?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'feelings', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l5-i03', 'sentence', 'Jestem zmęczony, ale ogólnie czuję się dobrze.', '疲れていますが、全体的には元気です。', 'I am tired, but generally I feel well.', 'martwić się、czuć się、potrzebowaćとbo/żebyを使って、状態と必要な時間を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'feelings', '["cefr:a2","scene:feelings","grammar:reflexive-verbs","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Jestem zmęczony, ale ogólnie czuję się dobrze","Jestem zmęczony, ale ogólnie czuję się dobrze."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'feelings', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l5-i04', 'sentence', 'Rozumiem, że to może być trudne.', 'それは難しいことかもしれませんね。', 'I understand that it may be difficult.', 'martwić się、czuć się、potrzebowaćとbo/żebyを使って、状態と必要な時間を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'feelings', '["cefr:a2","scene:feelings","grammar:reflexive-verbs","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Rozumiem, że to może być trudne","Rozumiem, że to może być trudne."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'feelings', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l5-i05', 'sentence', 'Potrzebuję chwili, żeby spokojnie pomyśleć.', '落ち着いて考えるために少し時間が必要です。', 'I need a moment to think calmly.', 'martwić się、czuć się、potrzebowaćとbo/żebyを使って、状態と必要な時間を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'feelings', '["cefr:a2","scene:feelings","grammar:reflexive-verbs","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Potrzebuję chwili, żeby spokojnie pomyśleć","Potrzebuję chwili, żeby spokojnie pomyśleć."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'feelings', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l5-i06', 'sentence', 'Nie przejmuj się, spróbujemy razem znaleźć rozwiązanie.', '心配しないで、一緒に解決策を探しましょう。', 'Do not worry, we will try to find a solution together.', 'martwić się、czuć się、potrzebowaćとbo/żebyを使って、状態と必要な時間を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'feelings', '["cefr:a2","scene:feelings","grammar:reflexive-verbs","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Nie przejmuj się, spróbujemy razem znaleźć rozwiązanie","Nie przejmuj się, spróbujemy razem znaleźć rozwiązanie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'feelings', 'neutral', 'male', 'partner', 'independent');
