INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u1-l6', 'a2-unit-1', 6, '一週間の出来事を雑談する', 'Krótka rozmowa o tygodniu', '男性話者の過去形 minął、miałem、odwiedziłem と、podobać się を使って感想を話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l6-i01', 'sentence', 'Jak ci minął tydzień?', '今週はどうでしたか？', 'How was your week?', '男性話者の過去形 minął、miałem、odwiedziłem と、podobać się を使って感想を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'small-talk', '["cefr:a2","scene:small-talk","grammar:past-tense","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Jak ci minął tydzień","Jak ci minął tydzień?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'small-talk', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l6-i02', 'sentence', 'Całkiem dobrze, tylko miałem dużo pracy.', 'まあまあでした、ただ仕事が多かったです。', 'Quite well, I just had a lot of work.', '男性話者の過去形 minął、miałem、odwiedziłem と、podobać się を使って感想を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'small-talk', '["cefr:a2","scene:small-talk","grammar:past-tense","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Całkiem dobrze, tylko miałem dużo pracy","Całkiem dobrze, tylko miałem dużo pracy."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'small-talk', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l6-i03', 'sentence', 'Wczoraj odwiedziłem ciekawą wystawę.', '昨日、面白い展覧会に行きました。', 'Yesterday I visited an interesting exhibition.', '男性話者の過去形 minął、miałem、odwiedziłem と、podobać się を使って感想を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'small-talk', '["cefr:a2","scene:small-talk","grammar:past-tense","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Wczoraj odwiedziłem ciekawą wystawę","Wczoraj odwiedziłem ciekawą wystawę."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'small-talk', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l6-i04', 'sentence', 'Naprawdę? Co najbardziej ci się podobało?', '本当ですか？何が一番気に入りましたか？', 'Really? What did you like most?', '男性話者の過去形 minął、miałem、odwiedziłem と、podobać się を使って感想を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'small-talk', '["cefr:a2","scene:small-talk","grammar:past-tense","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Naprawdę? Co najbardziej ci się podobało","Naprawdę? Co najbardziej ci się podobało?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'small-talk', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l6-i05', 'sentence', 'Najbardziej podobała mi się część o historii miasta.', '街の歴史についての部分が一番気に入りました。', 'I liked the part about the city''s history most.', '男性話者の過去形 minął、miałem、odwiedziłem と、podobać się を使って感想を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'small-talk', '["cefr:a2","scene:small-talk","grammar:past-tense","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Najbardziej podobała mi się część o historii miasta","Najbardziej podobała mi się część o historii miasta."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'small-talk', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u1-l6-i06', 'sentence', 'Chętnie zobaczę ją następnym razem.', '次回ぜひ見てみたいです。', 'I would gladly see it next time.', '男性話者の過去形 minął、miałem、odwiedziłem と、podobać się を使って感想を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'small-talk', '["cefr:a2","scene:small-talk","grammar:past-tense","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Chętnie zobaczę ją następnym razem","Chętnie zobaczę ją następnym razem."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'small-talk', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u1-l6-s1', 'a2-u1-l6', 1, 'choice', 'a2-u1-l6-i01', '「今週はどうでしたか？」に合うポーランド語を選びましょう。', '男性話者の過去形 minął、miałem、odwiedziłem と、podobać się を使って感想を話します。', '[{"value":"Jak ci minął tydzień?","label":"Jak ci minął tydzień?"},{"value":"Wczoraj odwiedziłem ciekawą wystawę.","label":"Wczoraj odwiedziłem ciekawą wystawę."},{"value":"Najbardziej podobała mi się część o historii miasta.","label":"Najbardziej podobała mi się część o historii miasta."},{"value":"Chętnie zobaczę ją następnym razem.","label":"Chętnie zobaczę ją następnym razem."}]', 'multiple_choice', 'meaning_to_polish', 'Jak ci minął tydzień?', '', '', '', '[]', 0, '意味から形を認識する');
