INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u2-l1', 'a2-unit-2', 1, '朝のルーティン', 'Poranek', 'zwykle、około、najpierw potem を使って、時刻と順序のある日課を説明します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l1-i01', 'sentence', 'Zwykle wstaję około siódmej.', '普段は7時ごろ起きます。', 'I usually get up around seven.', 'zwykle、około、najpierw potem を使って、時刻と順序のある日課を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'daily-routine', '["cefr:a2","scene:daily-routine","grammar:time-expressions","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Zwykle wstaję około siódmej","Zwykle wstaję około siódmej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'daily-routine', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l1-i02', 'sentence', 'O której zwykle zaczynasz dzień?', '普段は何時に一日を始めますか？', 'What time do you usually start your day?', 'zwykle、około、najpierw potem を使って、時刻と順序のある日課を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'daily-routine', '["cefr:a2","scene:daily-routine","grammar:time-expressions","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["O której zwykle zaczynasz dzień","O której zwykle zaczynasz dzień?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'daily-routine', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l1-i03', 'sentence', 'Najpierw robię sobie herbatę, a potem sprawdzam wiadomości.', 'まずお茶を入れ、そのあとニュースを確認します。', 'First I make tea, then I check the news.', 'zwykle、około、najpierw potem を使って、時刻と順序のある日課を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'daily-routine', '["cefr:a2","scene:daily-routine","grammar:time-expressions","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Najpierw robię sobie herbatę, a potem sprawdzam wiadomości","Najpierw robię sobie herbatę, a potem sprawdzam wiadomości."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'daily-routine', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l1-i04', 'sentence', 'Czy rano masz dużo czasu?', '朝は時間がありますか？', 'Do you have much time in the morning?', 'zwykle、około、najpierw potem を使って、時刻と順序のある日課を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'daily-routine', '["cefr:a2","scene:daily-routine","grammar:time-expressions","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy rano masz dużo czasu","Czy rano masz dużo czasu?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'daily-routine', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l1-i05', 'sentence', 'Wychodzę z domu przed ósmą.', '8時前に家を出ます。', 'I leave home before eight.', 'zwykle、około、najpierw potem を使って、時刻と順序のある日課を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'daily-routine', '["cefr:a2","scene:daily-routine","grammar:time-expressions","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Wychodzę z domu przed ósmą","Wychodzę z domu przed ósmą."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'daily-routine', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l1-i06', 'sentence', 'U mnie poranki zaczynają się bardzo wcześnie.', '私のところでは朝がとても早く始まります。', 'Mornings start very early where I live.', 'zwykle、około、najpierw potem を使って、時刻と順序のある日課を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'daily-routine', '["cefr:a2","scene:daily-routine","grammar:time-expressions","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["U mnie poranki zaczynają się bardzo wcześnie","U mnie poranki zaczynają się bardzo wcześnie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'daily-routine', 'neutral', 'male', 'partner', 'independent');
