INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u2-l2', 'a2-unit-2', 2, '曜日ごとの予定', 'Plan tygodnia', 'w poniedziałki、od ... do ...、przełożyć na を使って、曜日と予定変更を話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l2-i01', 'sentence', 'W poniedziałki pracuję z biura.', '月曜日はオフィスで働きます。', 'On Mondays I work from the office.', 'w poniedziałki、od ... do ...、przełożyć na を使って、曜日と予定変更を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'schedule', '["cefr:a2","scene:schedule","grammar:days-and-prepositions","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W poniedziałki pracuję z biura","W poniedziałki pracuję z biura."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'schedule', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l2-i02', 'sentence', 'W które dni pracujesz z domu?', '何曜日に家で働きますか？', 'On which days do you work from home?', 'w poniedziałki、od ... do ...、przełożyć na を使って、曜日と予定変更を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'schedule', '["cefr:a2","scene:schedule","grammar:days-and-prepositions","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["W które dni pracujesz z domu","W które dni pracujesz z domu?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'schedule', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l2-i03', 'sentence', 'We wtorek mam spotkanie od dziewiątej do jedenastej.', '火曜日は9時から11時まで会議があります。', 'On Tuesday I have a meeting from nine to eleven.', 'w poniedziałki、od ... do ...、przełożyć na を使って、曜日と予定変更を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'schedule', '["cefr:a2","scene:schedule","grammar:days-and-prepositions","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["We wtorek mam spotkanie od dziewiątej do jedenastej","We wtorek mam spotkanie od dziewiątej do jedenastej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'schedule', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l2-i04', 'sentence', 'Czy możemy przełożyć je na czwartek?', 'それを木曜日に変更できますか？', 'Can we move it to Thursday?', 'w poniedziałki、od ... do ...、przełożyć na を使って、曜日と予定変更を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'schedule', '["cefr:a2","scene:schedule","grammar:days-and-prepositions","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy możemy przełożyć je na czwartek","Czy możemy przełożyć je na czwartek?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'schedule', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l2-i05', 'sentence', 'W piątek kończę wcześniej.', '金曜日は早く終わります。', 'On Friday I finish earlier.', 'w poniedziałki、od ... do ...、przełożyć na を使って、曜日と予定変更を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'schedule', '["cefr:a2","scene:schedule","grammar:days-and-prepositions","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W piątek kończę wcześniej","W piątek kończę wcześniej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'schedule', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l2-i06', 'sentence', 'W takim razie pasuje mi piątek wieczorem.', 'それなら金曜日の夜が都合いいです。', 'In that case Friday evening works for me.', 'w poniedziałki、od ... do ...、przełożyć na を使って、曜日と予定変更を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'schedule', '["cefr:a2","scene:schedule","grammar:days-and-prepositions","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["W takim razie pasuje mi piątek wieczorem","W takim razie pasuje mi piątek wieczorem."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'schedule', 'neutral', 'male', 'partner', 'independent');
