INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u2-l3', 'a2-unit-2', 3, '天気と持ち物', 'Jaka będzie pogoda?', 'jest、padać、ma być、zrobić się を使い、予報を聞いて持ち物を判断します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l3-i01', 'sentence', 'Dzisiaj jest pochmurno, ale nie pada.', '今日は曇っていますが、雨は降っていません。', 'It is cloudy today, but it is not raining.', 'jest、padać、ma być、zrobić się を使い、予報を聞いて持ち物を判断します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'weather', '["cefr:a2","scene:weather","grammar:impersonal-weather","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Dzisiaj jest pochmurno, ale nie pada","Dzisiaj jest pochmurno, ale nie pada."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'weather', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l3-i02', 'sentence', 'Jaka jest dziś pogoda w twoim mieście?', '今日あなたの街の天気はどうですか？', 'What is the weather like in your city today?', 'jest、padać、ma być、zrobić się を使い、予報を聞いて持ち物を判断します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'weather', '["cefr:a2","scene:weather","grammar:impersonal-weather","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jaka jest dziś pogoda w twoim mieście","Jaka jest dziś pogoda w twoim mieście?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'weather', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l3-i03', 'sentence', 'Jutro ma być cieplej i słonecznie.', '明日はもっと暖かく晴れるそうです。', 'Tomorrow it is supposed to be warmer and sunny.', 'jest、padać、ma być、zrobić się を使い、予報を聞いて持ち物を判断します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'weather', '["cefr:a2","scene:weather","grammar:impersonal-weather","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Jutro ma być cieplej i słonecznie","Jutro ma być cieplej i słonecznie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'weather', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l3-i04', 'sentence', 'Czy potrzebuję parasola?', '傘は必要ですか？', 'Do I need an umbrella?', 'jest、padać、ma być、zrobić się を使い、予報を聞いて持ち物を判断します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'weather', '["cefr:a2","scene:weather","grammar:impersonal-weather","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy potrzebuję parasola","Czy potrzebuję parasola?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'weather', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l3-i05', 'sentence', 'Lepiej weź kurtkę, bo wieczorem zrobi się chłodno.', '上着を持ったほうがいいです、夜は涼しくなるので。', 'You had better take a jacket because it will get cool in the evening.', 'jest、padać、ma być、zrobić się を使い、予報を聞いて持ち物を判断します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'weather', '["cefr:a2","scene:weather","grammar:impersonal-weather","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Lepiej weź kurtkę, bo wieczorem zrobi się chłodno","Lepiej weź kurtkę, bo wieczorem zrobi się chłodno."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'weather', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l3-i06', 'sentence', 'Dzięki, sprawdzę jeszcze prognozę.', 'ありがとう、もう一度予報を確認します。', 'Thanks, I will check the forecast once more.', 'jest、padać、ma być、zrobić się を使い、予報を聞いて持ち物を判断します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'weather', '["cefr:a2","scene:weather","grammar:impersonal-weather","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Dzięki, sprawdzę jeszcze prognozę","Dzięki, sprawdzę jeszcze prognozę."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'weather', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u2-l3-s1', 'a2-u2-l3', 1, 'choice', 'a2-u2-l3-i01', '「今日は曇っていますが、雨は降っていません。」に合うポーランド語を選びましょう。', 'jest、padać、ma być、zrobić się を使い、予報を聞いて持ち物を判断します。', '[{"value":"Dzisiaj jest pochmurno, ale nie pada.","label":"Dzisiaj jest pochmurno, ale nie pada."},{"value":"Jutro ma być cieplej i słonecznie.","label":"Jutro ma być cieplej i słonecznie."},{"value":"Lepiej weź kurtkę, bo wieczorem zrobi się chłodno.","label":"Lepiej weź kurtkę, bo wieczorem zrobi się chłodno."},{"value":"Dzięki, sprawdzę jeszcze prognozę.","label":"Dzięki, sprawdzę jeszcze prognozę."}]', 'multiple_choice', 'meaning_to_polish', 'Dzisiaj jest pochmurno, ale nie pada.', '', '', '', '[]', 0, '意味から形を認識する');
