INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u2-l4', 'a2-unit-2', 4, '日付と時刻を合わせる', 'Data i godzina', '序数の生格・前置格と、o + 時刻を使って、日付と約束を確認します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l4-i01', 'sentence', 'Urodziny mam dwudziestego trzeciego maja.', '誕生日は5月23日です。', 'My birthday is on the twenty-third of May.', '序数の生格・前置格と、o + 時刻を使って、日付と約束を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'calendar', '["cefr:a2","scene:calendar","grammar:ordinal-dates","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Urodziny mam dwudziestego trzeciego maja","Urodziny mam dwudziestego trzeciego maja."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'calendar', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l4-i02', 'sentence', 'Kiedy masz urodziny?', '誕生日はいつですか？', 'When is your birthday?', '序数の生格・前置格と、o + 時刻を使って、日付と約束を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'calendar', '["cefr:a2","scene:calendar","grammar:ordinal-dates","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Kiedy masz urodziny","Kiedy masz urodziny?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'calendar', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l4-i03', 'sentence', 'W przyszłym tygodniu wypada święto.', '来週は祝日があります。', 'There is a holiday next week.', '序数の生格・前置格と、o + 時刻を使って、日付と約束を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'calendar', '["cefr:a2","scene:calendar","grammar:ordinal-dates","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W przyszłym tygodniu wypada święto","W przyszłym tygodniu wypada święto."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'calendar', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l4-i04', 'sentence', 'Czy sklep będzie wtedy otwarty?', 'そのとき店は開いていますか？', 'Will the shop be open then?', '序数の生格・前置格と、o + 時刻を使って、日付と約束を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'calendar', '["cefr:a2","scene:calendar","grammar:ordinal-dates","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy sklep będzie wtedy otwarty","Czy sklep będzie wtedy otwarty?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'calendar', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l4-i05', 'sentence', 'Spotkajmy się pierwszego czerwca o siedemnastej.', '6月1日の17時に会いましょう。', 'Let us meet on the first of June at five p.m.', '序数の生格・前置格と、o + 時刻を使って、日付と約束を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'calendar', '["cefr:a2","scene:calendar","grammar:ordinal-dates","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Spotkajmy się pierwszego czerwca o siedemnastej","Spotkajmy się pierwszego czerwca o siedemnastej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'calendar', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l4-i06', 'sentence', 'Zapisuję: pierwszy czerwca, godzina siedemnasta.', 'メモします。6月1日、17時ですね。', 'I am writing it down: the first of June, five p.m.', '序数の生格・前置格と、o + 時刻を使って、日付と約束を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'calendar', '["cefr:a2","scene:calendar","grammar:ordinal-dates","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Zapisuję: pierwszy czerwca, godzina siedemnasta","Zapisuję: pierwszy czerwca, godzina siedemnasta."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'calendar', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u2-l4-s1', 'a2-u2-l4', 1, 'choice', 'a2-u2-l4-i01', '「誕生日は5月23日です。」に合うポーランド語を選びましょう。', '序数の生格・前置格と、o + 時刻を使って、日付と約束を確認します。', '[{"value":"Urodziny mam dwudziestego trzeciego maja.","label":"Urodziny mam dwudziestego trzeciego maja."},{"value":"W przyszłym tygodniu wypada święto.","label":"W przyszłym tygodniu wypada święto."},{"value":"Spotkajmy się pierwszego czerwca o siedemnastej.","label":"Spotkajmy się pierwszego czerwca o siedemnastej."},{"value":"Zapisuję: pierwszy czerwca, godzina siedemnasta.","label":"Zapisuję: pierwszy czerwca, godzina siedemnasta."}]', 'multiple_choice', 'meaning_to_polish', 'Urodziny mam dwudziestego trzeciego maja.', '', '', '', '[]', 0, '意味から形を認識する');
