INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u2-l5', 'a2-unit-2', 5, '家事を分担する', 'Obowiązki domowe', 'wynosić、odkurzać、zajmę się tym と、czy możesz を使って家事の依頼と承諾をします。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l5-i01', 'sentence', 'Po pracy robię zakupy i gotuję kolację.', '仕事の後に買い物をして夕食を作ります。', 'After work I shop and cook dinner.', 'wynosić、odkurzać、zajmę się tym と、czy możesz を使って家事の依頼と承諾をします。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'chores', '["cefr:a2","scene:chores","grammar:imperative-and-modal","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Po pracy robię zakupy i gotuję kolację","Po pracy robię zakupy i gotuję kolację."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'chores', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l5-i02', 'sentence', 'Kto dzisiaj wynosi śmieci?', '今日は誰がごみを出しますか？', 'Who is taking out the rubbish today?', 'wynosić、odkurzać、zajmę się tym と、czy możesz を使って家事の依頼と承諾をします。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'chores', '["cefr:a2","scene:chores","grammar:imperative-and-modal","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Kto dzisiaj wynosi śmieci","Kto dzisiaj wynosi śmieci?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'chores', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l5-i03', 'sentence', 'W soboty sprzątam mieszkanie.', '土曜日はアパートを掃除します。', 'On Saturdays I clean the flat.', 'wynosić、odkurzać、zajmę się tym と、czy możesz を使って家事の依頼と承諾をします。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'chores', '["cefr:a2","scene:chores","grammar:imperative-and-modal","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W soboty sprzątam mieszkanie","W soboty sprzątam mieszkanie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'chores', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l5-i04', 'sentence', 'Czy możesz odkurzyć przed wizytą gości?', 'お客さんが来る前に掃除機をかけてもらえますか？', 'Can you vacuum before the guests visit?', 'wynosić、odkurzać、zajmę się tym と、czy możesz を使って家事の依頼と承諾をします。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'chores', '["cefr:a2","scene:chores","grammar:imperative-and-modal","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy możesz odkurzyć przed wizytą gości","Czy możesz odkurzyć przed wizytą gości?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'chores', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l5-i05', 'sentence', 'Jasne, zajmę się tym po obiedzie.', 'もちろん、昼食後にそれをやります。', 'Sure, I will take care of it after lunch.', 'wynosić、odkurzać、zajmę się tym と、czy możesz を使って家事の依頼と承諾をします。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'chores', '["cefr:a2","scene:chores","grammar:imperative-and-modal","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Jasne, zajmę się tym po obiedzie","Jasne, zajmę się tym po obiedzie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'chores', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l5-i06', 'sentence', 'Dziękuję, to bardzo mi pomoże.', 'ありがとう、とても助かります。', 'Thank you, that will help me a lot.', 'wynosić、odkurzać、zajmę się tym と、czy możesz を使って家事の依頼と承諾をします。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'chores', '["cefr:a2","scene:chores","grammar:imperative-and-modal","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Dziękuję, to bardzo mi pomoże","Dziękuję, to bardzo mi pomoże."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'chores', 'neutral', 'male', 'partner', 'independent');
