INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l6-i01', 'sentence', 'Staram się codziennie spacerować.', '毎日散歩するようにしています。', 'I try to go for a walk every day.', 'starać się、dbać o、częstotliwo数詞を使って、健康習慣と頻度を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'health-routine', '["cefr:a2","scene:health-routine","grammar:reflexive-and-frequency","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Staram się codziennie spacerować","Staram się codziennie spacerować."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'health-routine', 'neutral', 'male', 'learner', 'independent');
