INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l6-i03', 'sentence', 'Nie palę i piję dużo wody.', 'たばこを吸わず、水をたくさん飲みます。', 'I do not smoke and I drink a lot of water.', 'starać się、dbać o、częstotliwo数詞を使って、健康習慣と頻度を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'health-routine', '["cefr:a2","scene:health-routine","grammar:reflexive-and-frequency","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Nie palę i piję dużo wody","Nie palę i piję dużo wody."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'health-routine', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l6-i04', 'sentence', 'Czy regularnie uprawiasz sport?', '定期的にスポーツをしますか？', 'Do you exercise regularly?', 'starać się、dbać o、częstotliwo数詞を使って、健康習慣と頻度を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'health-routine', '["cefr:a2","scene:health-routine","grammar:reflexive-and-frequency","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy regularnie uprawiasz sport","Czy regularnie uprawiasz sport?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'health-routine', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u2-l6-i05', 'sentence', 'Dwa razy w tygodniu jeżdżę na rowerze.', '週に2回、自転車に乗ります。', 'I cycle twice a week.', 'starać się、dbać o、częstotliwo数詞を使って、健康習慣と頻度を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'health-routine', '["cefr:a2","scene:health-routine","grammar:reflexive-and-frequency","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Dwa razy w tygodniu jeżdżę na rowerze","Dwa razy w tygodniu jeżdżę na rowerze."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'health-routine', 'informal', 'male', 'learner', 'independent');
