INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u3-l1', 'a2-unit-3', 1, '昨日の出来事', 'Wczoraj', '男性話者の過去形 wróciłem、ugotowałem、obejrzałem と、最初に/そのあとを使います。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l1-i01', 'sentence', 'Wczoraj wróciłem późno do domu.', '昨日、遅く家に帰りました。', 'Yesterday I came home late.', '男性話者の過去形 wróciłem、ugotowałem、obejrzałem と、最初に/そのあとを使います。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'past-events', '["cefr:a2","scene:past-events","grammar:past-masculine","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Wczoraj wróciłem późno do domu","Wczoraj wróciłem późno do domu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'past-events', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l1-i02', 'sentence', 'Co robiłeś wczoraj wieczorem?', '昨日の夜は何をしましたか？', 'What did you do yesterday evening?', '男性話者の過去形 wróciłem、ugotowałem、obejrzałem と、最初に/そのあとを使います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'past-events', '["cefr:a2","scene:past-events","grammar:past-masculine","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Co robiłeś wczoraj wieczorem","Co robiłeś wczoraj wieczorem?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'past-events', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l1-i03', 'sentence', 'Najpierw ugotowałem kolację, a potem obejrzałem film.', 'まず夕食を作り、そのあと映画を見ました。', 'First I cooked dinner, then I watched a film.', '男性話者の過去形 wróciłem、ugotowałem、obejrzałem と、最初に/そのあとを使います。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'past-events', '["cefr:a2","scene:past-events","grammar:past-masculine","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Najpierw ugotowałem kolację, a potem obejrzałem film","Najpierw ugotowałem kolację, a potem obejrzałem film."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'past-events', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l1-i04', 'sentence', 'Jaki film oglądałeś?', 'どんな映画を見たのですか？', 'What film did you watch?', '男性話者の過去形 wróciłem、ugotowałem、obejrzałem と、最初に/そのあとを使います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'past-events', '["cefr:a2","scene:past-events","grammar:past-masculine","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jaki film oglądałeś","Jaki film oglądałeś?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'past-events', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l1-i05', 'sentence', 'To była komedia, więc dużo się śmiałem.', 'コメディーだったので、たくさん笑いました。', 'It was a comedy, so I laughed a lot.', '男性話者の過去形 wróciłem、ugotowałem、obejrzałem と、最初に/そのあとを使います。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'past-events', '["cefr:a2","scene:past-events","grammar:past-masculine","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["To była komedia, więc dużo się śmiałem","To była komedia, więc dużo się śmiałem."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'past-events', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l1-i06', 'sentence', 'Brzmi jak udany wieczór.', '楽しい夜だったようですね。', 'It sounds like a successful evening.', '男性話者の過去形 wróciłem、ugotowałem、obejrzałem と、最初に/そのあとを使います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'past-events', '["cefr:a2","scene:past-events","grammar:past-masculine","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Brzmi jak udany wieczór","Brzmi jak udany wieczór."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'past-events', 'neutral', 'male', 'partner', 'independent');
