INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u3-l2', 'a2-unit-3', 2, '週末の外出', 'Miniony weekend', 'pojechałem、spędziliśmy、robiliśmyを使い、過去の移動と共同活動を順序立てて話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l2-i01', 'sentence', 'W zeszły weekend pojechałem nad jezioro.', '先週末、湖へ行きました。', 'Last weekend I went to a lake.', 'pojechałem、spędziliśmy、robiliśmyを使い、過去の移動と共同活動を順序立てて話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'weekend', '["cefr:a2","scene:weekend","grammar:past-plural","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W zeszły weekend pojechałem nad jezioro","W zeszły weekend pojechałem nad jezioro."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'weekend', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l2-i02', 'sentence', 'Z kim tam pojechałeś?', '誰とそこへ行ったのですか？', 'Who did you go there with?', 'pojechałem、spędziliśmy、robiliśmyを使い、過去の移動と共同活動を順序立てて話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'weekend', '["cefr:a2","scene:weekend","grammar:past-plural","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Z kim tam pojechałeś","Z kim tam pojechałeś?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'weekend', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l2-i03', 'sentence', 'Pojechałem z przyjaciółmi i spędziliśmy tam cały dzień.', '友達と行き、そこで一日過ごしました。', 'I went with friends and we spent the whole day there.', 'pojechałem、spędziliśmy、robiliśmyを使い、過去の移動と共同活動を順序立てて話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'weekend', '["cefr:a2","scene:weekend","grammar:past-plural","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Pojechałem z przyjaciółmi i spędziliśmy tam cały dzień","Pojechałem z przyjaciółmi i spędziliśmy tam cały dzień."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'weekend', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l2-i04', 'sentence', 'Co robiliście na miejscu?', '現地では何をしましたか？', 'What did you do there?', 'pojechałem、spędziliśmy、robiliśmyを使い、過去の移動と共同活動を順序立てて話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'weekend', '["cefr:a2","scene:weekend","grammar:past-plural","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Co robiliście na miejscu","Co robiliście na miejscu?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'weekend', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l2-i05', 'sentence', 'Spacerowaliśmy, rozmawialiśmy i zrobiliśmy zdjęcia.', '散歩し、話し、写真を撮りました。', 'We walked, talked and took photos.', 'pojechałem、spędziliśmy、robiliśmyを使い、過去の移動と共同活動を順序立てて話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'weekend', '["cefr:a2","scene:weekend","grammar:past-plural","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Spacerowaliśmy, rozmawialiśmy i zrobiliśmy zdjęcia","Spacerowaliśmy, rozmawialiśmy i zrobiliśmy zdjęcia."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'weekend', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l2-i06', 'sentence', 'Szkoda, że nie mogłem dołączyć.', '参加できなくて残念です。', 'It is a pity I could not join you.', 'pojechałem、spędziliśmy、robiliśmyを使い、過去の移動と共同活動を順序立てて話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'weekend', '["cefr:a2","scene:weekend","grammar:past-plural","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Szkoda, że nie mogłem dołączyć","Szkoda, że nie mogłem dołączyć."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'weekend', 'neutral', 'male', 'partner', 'independent');
