INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u3-l3', 'a2-unit-3', 3, '土曜日の計画', 'Plan na sobotę', 'zamierzać、chciałbym、jeśli を使い、予定と条件付きの代案を話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l3-i01', 'sentence', 'W sobotę zamierzam odwiedzić muzeum.', '土曜日は博物館を訪れるつもりです。', 'On Saturday I intend to visit a museum.', 'zamierzać、chciałbym、jeśli を使い、予定と条件付きの代案を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'plans', '["cefr:a2","scene:plans","grammar:future-intention","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W sobotę zamierzam odwiedzić muzeum","W sobotę zamierzam odwiedzić muzeum."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'plans', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l3-i02', 'sentence', 'Masz już jakiś plan na sobotę?', '土曜日の予定はもうありますか？', 'Do you already have a plan for Saturday?', 'zamierzać、chciałbym、jeśli を使い、予定と条件付きの代案を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'plans', '["cefr:a2","scene:plans","grammar:future-intention","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Masz już jakiś plan na sobotę","Masz już jakiś plan na sobotę?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'plans', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l3-i03', 'sentence', 'Chciałbym też zjeść obiad w centrum.', '中心部で昼食も食べたいです。', 'I would also like to have lunch in the centre.', 'zamierzać、chciałbym、jeśli を使い、予定と条件付きの代案を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'plans', '["cefr:a2","scene:plans","grammar:future-intention","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym też zjeść obiad w centrum","Chciałbym też zjeść obiad w centrum."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'plans', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l3-i04', 'sentence', 'O której planujesz wyjść?', '何時に出発する予定ですか？', 'What time are you planning to leave?', 'zamierzać、chciałbym、jeśli を使い、予定と条件付きの代案を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'plans', '["cefr:a2","scene:plans","grammar:future-intention","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["O której planujesz wyjść","O której planujesz wyjść?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'plans', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l3-i05', 'sentence', 'Wyjdę około południa, jeśli nie będzie padać.', '雨が降らなければ、正午ごろ出ます。', 'I will leave around noon if it does not rain.', 'zamierzać、chciałbym、jeśli を使い、予定と条件付きの代案を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'plans', '["cefr:a2","scene:plans","grammar:future-intention","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Wyjdę około południa, jeśli nie będzie padać","Wyjdę około południa, jeśli nie będzie padać."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'plans', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l3-i06', 'sentence', 'Jeśli chcesz, możemy spotkać się później.', 'よければ、あとで会えます。', 'If you want, we can meet later.', 'zamierzać、chciałbym、jeśli を使い、予定と条件付きの代案を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'plans', '["cefr:a2","scene:plans","grammar:future-intention","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jeśli chcesz, możemy spotkać się później","Jeśli chcesz, możemy spotkać się później."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'plans', 'informal', 'male', 'partner', 'independent');
