INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u3-l4', 'a2-unit-3', 4, '未来の希望と目標', 'Moje cele', 'chciałbym、będę ćwiczył、żebyを使い、希望・具体的な行動・目的を結びつけます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l4-i01', 'sentence', 'W przyszłym roku chciałbym lepiej mówić po polsku.', '来年はもっと上手にポーランド語を話したいです。', 'Next year I would like to speak Polish better.', 'chciałbym、będę ćwiczył、żebyを使い、希望・具体的な行動・目的を結びつけます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'goals', '["cefr:a2","scene:goals","grammar:future-and-wishes","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W przyszłym roku chciałbym lepiej mówić po polsku","W przyszłym roku chciałbym lepiej mówić po polsku."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'goals', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l4-i02', 'sentence', 'Czego chciałbyś nauczyć się w tym roku?', '今年は何を学びたいですか？', 'What would you like to learn this year?', 'chciałbym、będę ćwiczył、żebyを使い、希望・具体的な行動・目的を結びつけます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'goals', '["cefr:a2","scene:goals","grammar:future-and-wishes","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czego chciałbyś nauczyć się w tym roku","Czego chciałbyś nauczyć się w tym roku?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'goals', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l4-i03', 'sentence', 'Będę codziennie ćwiczył krótkie rozmowy.', '毎日短い会話を練習します。', 'I will practise short conversations every day.', 'chciałbym、będę ćwiczył、żebyを使い、希望・具体的な行動・目的を結びつけます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'goals', '["cefr:a2","scene:goals","grammar:future-and-wishes","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Będę codziennie ćwiczył krótkie rozmowy","Będę codziennie ćwiczył krótkie rozmowy."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'goals', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l4-i04', 'sentence', 'Czy masz jakiś konkretny cel?', '具体的な目標はありますか？', 'Do you have a specific goal?', 'chciałbym、będę ćwiczył、żebyを使い、希望・具体的な行動・目的を結びつけます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'goals', '["cefr:a2","scene:goals","grammar:future-and-wishes","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy masz jakiś konkretny cel","Czy masz jakiś konkretny cel?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'goals', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l4-i05', 'sentence', 'Chcę swobodnie załatwiać sprawy w urzędzie.', '役所の用事を気軽に済ませられるようになりたいです。', 'I want to handle matters at an office confidently.', 'chciałbym、będę ćwiczył、żebyを使い、希望・具体的な行動・目的を結びつけます。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'goals', '["cefr:a2","scene:goals","grammar:future-and-wishes","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chcę swobodnie załatwiać sprawy w urzędzie","Chcę swobodnie załatwiać sprawy w urzędzie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'goals', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l4-i06', 'sentence', 'To praktyczny i bardzo konkretny plan.', '実用的で、とても具体的な計画ですね。', 'That is a practical and very concrete plan.', 'chciałbym、będę ćwiczył、żebyを使い、希望・具体的な行動・目的を結びつけます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'goals', '["cefr:a2","scene:goals","grammar:future-and-wishes","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["To praktyczny i bardzo konkretny plan","To praktyczny i bardzo konkretny plan."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'goals', 'informal', 'male', 'partner', 'independent');
