INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u3-l5', 'a2-unit-3', 5, '理由を説明する', 'Dlaczego zostałem w domu', 'ponieważ、bo、musieć、po odpoczynkuを使って、理由と状態の変化を説明します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l5-i01', 'sentence', 'Nie poszedłem na spacer, ponieważ bolała mnie głowa.', '頭が痛かったので、散歩に行きませんでした。', 'I did not go for a walk because I had a headache.', 'ponieważ、bo、musieć、po odpoczynkuを使って、理由と状態の変化を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'reasons', '["cefr:a2","scene:reasons","grammar:because-and-infinitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Nie poszedłem na spacer, ponieważ bolała mnie głowa","Nie poszedłem na spacer, ponieważ bolała mnie głowa."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'reasons', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l5-i02', 'sentence', 'Dlaczego zostałeś dziś w domu?', '今日はなぜ家にいたのですか？', 'Why did you stay home today?', 'ponieważ、bo、musieć、po odpoczynkuを使って、理由と状態の変化を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'reasons', '["cefr:a2","scene:reasons","grammar:because-and-infinitive","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Dlaczego zostałeś dziś w domu","Dlaczego zostałeś dziś w domu?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'reasons', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l5-i03', 'sentence', 'Zostałem w domu, bo musiałem odpocząć.', '休まなければならなかったので、家にいました。', 'I stayed home because I had to rest.', 'ponieważ、bo、musieć、po odpoczynkuを使って、理由と状態の変化を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'reasons', '["cefr:a2","scene:reasons","grammar:because-and-infinitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Zostałem w domu, bo musiałem odpocząć","Zostałem w domu, bo musiałem odpocząć."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'reasons', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l5-i04', 'sentence', 'Czy czujesz się już lepiej?', 'もう気分はよくなりましたか？', 'Do you feel better now?', 'ponieważ、bo、musieć、po odpoczynkuを使って、理由と状態の変化を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'reasons', '["cefr:a2","scene:reasons","grammar:because-and-infinitive","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy czujesz się już lepiej","Czy czujesz się już lepiej?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'reasons', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l5-i05', 'sentence', 'Tak, po odpoczynku jest mi znacznie lepiej.', 'はい、休んだらずっとよくなりました。', 'Yes, I feel much better after resting.', 'ponieważ、bo、musieć、po odpoczynkuを使って、理由と状態の変化を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'reasons', '["cefr:a2","scene:reasons","grammar:because-and-infinitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tak, po odpoczynku jest mi znacznie lepiej","Tak, po odpoczynku jest mi znacznie lepiej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'reasons', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l5-i06', 'sentence', 'Dobrze, nie przemęczaj się dzisiaj.', 'よかった、今日は無理をしないでください。', 'Good, do not overwork yourself today.', 'ponieważ、bo、musieć、po odpoczynkuを使って、理由と状態の変化を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'reasons', '["cefr:a2","scene:reasons","grammar:because-and-infinitive","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Dobrze, nie przemęczaj się dzisiaj","Dobrze, nie przemęczaj się dzisiaj."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'reasons', 'neutral', 'male', 'partner', 'independent');
