INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u3-l6', 'a2-unit-3', 6, '用事を順番に報告する', 'Co załatwiłem', 'najpierw potem、wpłacić、zapytać、udać sięを使い、複数の用事の完了を報告します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l6-i01', 'sentence', 'Najpierw pojechałem do banku, a potem zrobiłem zakupy.', 'まず銀行へ行き、そのあと買い物をしました。', 'First I went to the bank, then I went shopping.', 'najpierw potem、wpłacić、zapytać、udać sięを使い、複数の用事の完了を報告します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'errands', '["cefr:a2","scene:errands","grammar:past-perfective","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Najpierw pojechałem do banku, a potem zrobiłem zakupy","Najpierw pojechałem do banku, a potem zrobiłem zakupy."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'errands', 'neutral', 'male', 'learner', 'independent');
