INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u3-l6-i06', 'sentence', 'To dobrze, że udało ci się wszystko załatwić.', '全部済ませられてよかったですね。', 'It is good that you managed to take care of everything.', 'najpierw potem、wpłacić、zapytać、udać sięを使い、複数の用事の完了を報告します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'errands', '["cefr:a2","scene:errands","grammar:past-perfective","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["To dobrze, że udało ci się wszystko załatwić","To dobrze, że udało ci się wszystko załatwić."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'errands', 'informal', 'male', 'partner', 'independent');
