INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u4-l1', 'a2-unit-4', 1, '趣味を詳しく話す', 'Moje zainteresowania', 'interesować się + 造格、lubić + 対格を使い、趣味と好きな対象を説明します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l1-i01', 'sentence', 'Interesuję się fotografią uliczną.', 'ストリート写真に興味があります。', 'I am interested in street photography.', 'interesować się + 造格、lubić + 対格を使い、趣味と好きな対象を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'hobbies', '["cefr:a2","scene:hobbies","grammar:instrumental-case","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Interesuję się fotografią uliczną","Interesuję się fotografią uliczną."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'hobbies', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l1-i02', 'sentence', 'Czym interesujesz się poza pracą?', '仕事以外では何に興味がありますか？', 'What are you interested in besides work?', 'interesować się + 造格、lubić + 対格を使い、趣味と好きな対象を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'hobbies', '["cefr:a2","scene:hobbies","grammar:instrumental-case","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czym interesujesz się poza pracą","Czym interesujesz się poza pracą?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'hobbies', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l1-i03', 'sentence', 'Lubię robić zdjęcia starych kamienic.', '古い建物の写真を撮るのが好きです。', 'I like taking photos of old townhouses.', 'interesować się + 造格、lubić + 対格を使い、趣味と好きな対象を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'hobbies', '["cefr:a2","scene:hobbies","grammar:instrumental-case","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Lubię robić zdjęcia starych kamienic","Lubię robić zdjęcia starych kamienic."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'hobbies', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l1-i04', 'sentence', 'Wolisz fotografować ludzi czy budynki?', '人と建物のどちらを撮るのが好きですか？', 'Do you prefer photographing people or buildings?', 'interesować się + 造格、lubić + 対格を使い、趣味と好きな対象を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'hobbies', '["cefr:a2","scene:hobbies","grammar:instrumental-case","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Wolisz fotografować ludzi czy budynki","Wolisz fotografować ludzi czy budynki?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'hobbies', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l1-i05', 'sentence', 'Najbardziej lubię spokojne poranki bez tłumu.', '人混みのない静かな朝が一番好きです。', 'I like quiet mornings without crowds most.', 'interesować się + 造格、lubić + 対格を使い、趣味と好きな対象を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'hobbies', '["cefr:a2","scene:hobbies","grammar:instrumental-case","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Najbardziej lubię spokojne poranki bez tłumu","Najbardziej lubię spokojne poranki bez tłumu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'hobbies', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l1-i06', 'sentence', 'Rozumiem, cisza pomaga zauważyć szczegóły.', 'なるほど、静けさは細部に気づく助けになりますね。', 'I see, silence helps you notice details.', 'interesować się + 造格、lubić + 対格を使い、趣味と好きな対象を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'hobbies', '["cefr:a2","scene:hobbies","grammar:instrumental-case","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Rozumiem, cisza pomaga zauważyć szczegóły","Rozumiem, cisza pomaga zauważyć szczegóły."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'hobbies', 'informal', 'male', 'partner', 'independent');
