INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u4-l2', 'a2-unit-4', 2, '値段と品質を比較する', 'Co jest lepsze?', 'tańszy、lepszy、droższy niż と wartoを使い、価格と品質を比較して選びます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l2-i01', 'sentence', 'Ten sklep jest tańszy niż tamten.', 'この店はあの店より安いです。', 'This shop is cheaper than that one.', 'tańszy、lepszy、droższy niż と wartoを使い、価格と品質を比較して選びます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'shopping-comparison', '["cefr:a2","scene:shopping-comparison","grammar:comparative-adjectives","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Ten sklep jest tańszy niż tamten","Ten sklep jest tańszy niż tamten."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'shopping-comparison', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l2-i02', 'sentence', 'Który produkt jest według ciebie lepszy?', 'あなたの考えでは、どの商品がよいですか？', 'Which product is better in your opinion?', 'tańszy、lepszy、droższy niż と wartoを使い、価格と品質を比較して選びます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'shopping-comparison', '["cefr:a2","scene:shopping-comparison","grammar:comparative-adjectives","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Który produkt jest według ciebie lepszy","Który produkt jest według ciebie lepszy?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'shopping-comparison', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l2-i03', 'sentence', 'Ten ma lepszy skład, ale jest trochę droższy.', 'こちらは成分がよいですが、少し高いです。', 'This one has better ingredients, but it is a little more expensive.', 'tańszy、lepszy、droższy niż と wartoを使い、価格と品質を比較して選びます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'shopping-comparison', '["cefr:a2","scene:shopping-comparison","grammar:comparative-adjectives","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Ten ma lepszy skład, ale jest trochę droższy","Ten ma lepszy skład, ale jest trochę droższy."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'shopping-comparison', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l2-i04', 'sentence', 'Czy różnica w cenie jest duża?', '価格差は大きいですか？', 'Is the difference in price large?', 'tańszy、lepszy、droższy niż と wartoを使い、価格と品質を比較して選びます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'shopping-comparison', '["cefr:a2","scene:shopping-comparison","grammar:comparative-adjectives","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy różnica w cenie jest duża","Czy różnica w cenie jest duża?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'shopping-comparison', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l2-i05', 'sentence', 'Nie, za lepszą jakość warto dopłacić.', 'いいえ、品質がよいなら追加で払う価値があります。', 'No, it is worth paying extra for better quality.', 'tańszy、lepszy、droższy niż と wartoを使い、価格と品質を比較して選びます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'shopping-comparison', '["cefr:a2","scene:shopping-comparison","grammar:comparative-adjectives","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Nie, za lepszą jakość warto dopłacić","Nie, za lepszą jakość warto dopłacić."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'shopping-comparison', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l2-i06', 'sentence', 'W takim razie wybierzmy ten produkt.', 'それならこの商品を選びましょう。', 'In that case let us choose this product.', 'tańszy、lepszy、droższy niż と wartoを使い、価格と品質を比較して選びます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'shopping-comparison', '["cefr:a2","scene:shopping-comparison","grammar:comparative-adjectives","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["W takim razie wybierzmy ten produkt","W takim razie wybierzmy ten produkt."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'shopping-comparison', 'neutral', 'male', 'partner', 'independent');
