INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u4-l3', 'a2-unit-4', 3, '映画と劇場に誘う', 'Kino czy teatr?', 'iść do kina/teatru、na film、zarezerwowaćを使い、文化イベントの好みと予約を話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l3-i01', 'sentence', 'W piątek idę do kina na polski film.', '金曜日にポーランド映画を見に映画館へ行きます。', 'On Friday I am going to the cinema for a Polish film.', 'iść do kina/teatru、na film、zarezerwowaćを使い、文化イベントの好みと予約を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'culture', '["cefr:a2","scene:culture","grammar:accusative-and-prepositions","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W piątek idę do kina na polski film","W piątek idę do kina na polski film."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'culture', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l3-i02', 'sentence', 'Na jaki film chcesz iść?', 'どの映画を見に行きたいですか？', 'What film do you want to see?', 'iść do kina/teatru、na film、zarezerwowaćを使い、文化イベントの好みと予約を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'culture', '["cefr:a2","scene:culture","grammar:accusative-and-prepositions","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Na jaki film chcesz iść","Na jaki film chcesz iść?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'culture', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l3-i03', 'sentence', 'Na nową komedię, bo lubię lekkie historie.', '新しいコメディーです。軽い物語が好きなので。', 'A new comedy, because I like light stories.', 'iść do kina/teatru、na film、zarezerwowaćを使い、文化イベントの好みと予約を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'culture', '["cefr:a2","scene:culture","grammar:accusative-and-prepositions","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Na nową komedię, bo lubię lekkie historie","Na nową komedię, bo lubię lekkie historie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'culture', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l3-i04', 'sentence', 'Wolisz kino czy teatr?', '映画館と劇場のどちらが好きですか？', 'Do you prefer the cinema or the theatre?', 'iść do kina/teatru、na film、zarezerwowaćを使い、文化イベントの好みと予約を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'culture', '["cefr:a2","scene:culture","grammar:accusative-and-prepositions","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Wolisz kino czy teatr","Wolisz kino czy teatr?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'culture', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l3-i05', 'sentence', 'Zwykle wybieram teatr, ale dziś mam ochotę na kino.', '普段は劇場を選びますが、今日は映画館に行きたいです。', 'I usually choose the theatre, but today I feel like going to the cinema.', 'iść do kina/teatru、na film、zarezerwowaćを使い、文化イベントの好みと予約を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'culture', '["cefr:a2","scene:culture","grammar:accusative-and-prepositions","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Zwykle wybieram teatr, ale dziś mam ochotę na kino","Zwykle wybieram teatr, ale dziś mam ochotę na kino."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'culture', 'neutral', 'male', 'learner', 'independent');
