INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u4-l3-s14', 'a2-u4-l3', 14, 'input', 'a2-u4-l3-i06', '「私たちの席を2つ予約できます。」をポーランド語で言いましょう。', 'iść do kina/teatru、na film、zarezerwowaćを使い、文化イベントの好みと予約を話します。', '[]', 'free_input', 'meaning_to_polish', 'Mogę zarezerwować dla nas dwa miejsca.', '', '', '', '[]', 2, '手がかりなしで思い出す');
INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u4-l4', 'a2-unit-4', 4, 'スポーツの頻度と好み', 'Sport razem', 'uprawiać sport、raz w tygodniu、w grupieを使い、運動の頻度と一人/集団の好みを話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l4-i01', 'sentence', 'W weekend gram w siatkówkę z sąsiadami.', '週末は近所の人とバレーボールをします。', 'At the weekend I play volleyball with neighbours.', 'uprawiać sport、raz w tygodniu、w grupieを使い、運動の頻度と一人/集団の好みを話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'sport', '["cefr:a2","scene:sport","grammar:frequency-and-instrumental","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W weekend gram w siatkówkę z sąsiadami","W weekend gram w siatkówkę z sąsiadami."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'sport', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l4-i02', 'sentence', 'Jak często uprawiasz sport?', 'どのくらいの頻度で運動しますか？', 'How often do you exercise?', 'uprawiać sport、raz w tygodniu、w grupieを使い、運動の頻度と一人/集団の好みを話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'sport', '["cefr:a2","scene:sport","grammar:frequency-and-instrumental","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jak często uprawiasz sport","Jak często uprawiasz sport?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'sport', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l4-i03', 'sentence', 'Raz w tygodniu chodzę na basen.', '週に1回プールへ行きます。', 'I go to the swimming pool once a week.', 'uprawiać sport、raz w tygodniu、w grupieを使い、運動の頻度と一人/集団の好みを話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'sport', '["cefr:a2","scene:sport","grammar:frequency-and-instrumental","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Raz w tygodniu chodzę na basen","Raz w tygodniu chodzę na basen."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'sport', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l4-i04', 'sentence', 'Wolisz ćwiczyć sam czy w grupie?', '一人とグループのどちらで運動したいですか？', 'Do you prefer exercising alone or in a group?', 'uprawiać sport、raz w tygodniu、w grupieを使い、運動の頻度と一人/集団の好みを話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'sport', '["cefr:a2","scene:sport","grammar:frequency-and-instrumental","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Wolisz ćwiczyć sam czy w grupie","Wolisz ćwiczyć sam czy w grupie?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'sport', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l4-i05', 'sentence', 'W grupie łatwiej mi zachować regularność.', 'グループのほうが定期的に続けやすいです。', 'It is easier for me to stay regular in a group.', 'uprawiać sport、raz w tygodniu、w grupieを使い、運動の頻度と一人/集団の好みを話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'sport', '["cefr:a2","scene:sport","grammar:frequency-and-instrumental","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W grupie łatwiej mi zachować regularność","W grupie łatwiej mi zachować regularność."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'sport', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l4-i06', 'sentence', 'To prawda, razem jest bardziej motywująco.', '確かに、一緒のほうがやる気が出ますね。', 'That is true, it is more motivating together.', 'uprawiać sport、raz w tygodniu、w grupieを使い、運動の頻度と一人/集団の好みを話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'sport', '["cefr:a2","scene:sport","grammar:frequency-and-instrumental","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["To prawda, razem jest bardziej motywująco","To prawda, razem jest bardziej motywująco."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'sport', 'informal', 'male', 'partner', 'independent');
