INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u4-l5', 'a2-unit-4', 5, '祝日と文化の違い', 'Święta i zwyczaje', 'w moim kraju、spędzać święta、zwyczajを使い、自国とポーランドの習慣を比較します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l5-i01', 'sentence', 'W moim kraju święta spędza się inaczej.', '私の国では祝日の過ごし方が違います。', 'In my country holidays are spent differently.', 'w moim kraju、spędzać święta、zwyczajを使い、自国とポーランドの習慣を比較します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'holidays', '["cefr:a2","scene:holidays","grammar:impersonal-and-genitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W moim kraju święta spędza się inaczej","W moim kraju święta spędza się inaczej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'holidays', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l5-i02', 'sentence', 'Jakie zwyczaje są ważne w twojej rodzinie?', 'あなたの家族ではどんな習慣が大切ですか？', 'What customs are important in your family?', 'w moim kraju、spędzać święta、zwyczajを使い、自国とポーランドの習慣を比較します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'holidays', '["cefr:a2","scene:holidays","grammar:impersonal-and-genitive","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jakie zwyczaje są ważne w twojej rodzinie","Jakie zwyczaje są ważne w twojej rodzinie?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'holidays', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l5-i03', 'sentence', 'W Wigilię spotykamy się przy wspólnym stole.', 'クリスマスイブには同じ食卓を囲みます。', 'On Christmas Eve we meet around a shared table.', 'w moim kraju、spędzać święta、zwyczajを使い、自国とポーランドの習慣を比較します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'holidays', '["cefr:a2","scene:holidays","grammar:impersonal-and-genitive","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W Wigilię spotykamy się przy wspólnym stole","W Wigilię spotykamy się przy wspólnym stole."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'holidays', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l5-i04', 'sentence', 'Czy masz jakieś ulubione polskie święto?', '好きなポーランドの祝日はありますか？', 'Do you have a favourite Polish holiday?', 'w moim kraju、spędzać święta、zwyczajを使い、自国とポーランドの習慣を比較します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'holidays', '["cefr:a2","scene:holidays","grammar:impersonal-and-genitive","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy masz jakieś ulubione polskie święto","Czy masz jakieś ulubione polskie święto?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'holidays', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l5-i05', 'sentence', 'Lubię pierwszy dzień wiosny, bo wszyscy wychodzą na spacer.', '春の初日が好きです。みんな散歩に出るからです。', 'I like the first day of spring because everyone goes for a walk.', 'w moim kraju、spędzać święta、zwyczajを使い、自国とポーランドの習慣を比較します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'holidays', '["cefr:a2","scene:holidays","grammar:impersonal-and-genitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Lubię pierwszy dzień wiosny, bo wszyscy wychodzą na spacer","Lubię pierwszy dzień wiosny, bo wszyscy wychodzą na spacer."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'holidays', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l5-i06', 'sentence', 'Ciekawe, chętnie poznam więcej takich zwyczajów.', '面白いですね、そうした習慣をもっと知りたいです。', 'Interesting, I would gladly learn more such customs.', 'w moim kraju、spędzać święta、zwyczajを使い、自国とポーランドの習慣を比較します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'holidays', '["cefr:a2","scene:holidays","grammar:impersonal-and-genitive","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Ciekawe, chętnie poznam więcej takich zwyczajów","Ciekawe, chętnie poznam więcej takich zwyczajów."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'holidays', 'neutral', 'male', 'partner', 'independent');
