INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u4-l6', 'a2-unit-4', 6, 'ポーランド語メディアを使う', 'Uczę się z mediów', 'słuchać podcastu、rozumieć temat、potrzebować powtórkiを使い、聞き取りと学習戦略を話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l6-i01', 'sentence', 'Ostatnio słucham podcastu po polsku.', '最近ポーランド語のポッドキャストを聞いています。', 'Recently I have been listening to a podcast in Polish.', 'słuchać podcastu、rozumieć temat、potrzebować powtórkiを使い、聞き取りと学習戦略を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'media', '["cefr:a2","scene:media","grammar:object-pronouns","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Ostatnio słucham podcastu po polsku","Ostatnio słucham podcastu po polsku."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'media', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l6-i02', 'sentence', 'Czy rozumiesz już większość takich nagrań?', 'もうそのような録音の大部分を理解できますか？', 'Do you already understand most of such recordings?', 'słuchać podcastu、rozumieć temat、potrzebować powtórkiを使い、聞き取りと学習戦略を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'media', '["cefr:a2","scene:media","grammar:object-pronouns","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy rozumiesz już większość takich nagrań","Czy rozumiesz już większość takich nagrań?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'media', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l6-i03', 'sentence', 'Rozumiem główny temat, ale czasem potrzebuję powtórki.', '大意は分かりますが、ときどき繰り返しが必要です。', 'I understand the main topic, but sometimes I need a repeat.', 'słuchać podcastu、rozumieć temat、potrzebować powtórkiを使い、聞き取りと学習戦略を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'media', '["cefr:a2","scene:media","grammar:object-pronouns","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Rozumiem główny temat, ale czasem potrzebuję powtórki","Rozumiem główny temat, ale czasem potrzebuję powtórki."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'media', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l6-i04', 'sentence', 'Co robisz, kiedy nie znasz słowa?', '知らない単語があるときはどうしますか？', 'What do you do when you do not know a word?', 'słuchać podcastu、rozumieć temat、potrzebować powtórkiを使い、聞き取りと学習戦略を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'media', '["cefr:a2","scene:media","grammar:object-pronouns","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Co robisz, kiedy nie znasz słowa","Co robisz, kiedy nie znasz słowa?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'media', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l6-i05', 'sentence', 'Zapisuję je i sprawdzam znaczenie po rozmowie.', 'それを書き留め、会話のあとで意味を調べます。', 'I write it down and check the meaning after the conversation.', 'słuchać podcastu、rozumieć temat、potrzebować powtórkiを使い、聞き取りと学習戦略を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'media', '["cefr:a2","scene:media","grammar:object-pronouns","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Zapisuję je i sprawdzam znaczenie po rozmowie","Zapisuję je i sprawdzam znaczenie po rozmowie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'media', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u4-l6-i06', 'sentence', 'To dobra strategia do samodzielnej nauki.', '自分で学ぶためのよい方法ですね。', 'That is a good strategy for independent learning.', 'słuchać podcastu、rozumieć temat、potrzebować powtórkiを使い、聞き取りと学習戦略を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'media', '["cefr:a2","scene:media","grammar:object-pronouns","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["To dobra strategia do samodzielnej nauki","To dobra strategia do samodzielnej nauki."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'media', 'neutral', 'male', 'partner', 'independent');
