INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l1-i01', 'sentence', 'Czy możesz mi powiedzieć, jak dojść do poczty?', '郵便局への行き方を教えてもらえますか？', 'Can you tell me how to get to the post office?', 'dojść do + 生格、idź、skręć、przyを使い、道を尋ねて案内を理解します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'directions', '["cefr:a2","scene:directions","grammar:imperative-and-locative","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy możesz mi powiedzieć, jak dojść do poczty","Czy możesz mi powiedzieć, jak dojść do poczty?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'directions', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l1-i02', 'sentence', 'Czego szukasz?', '何を探していますか？', 'What are you looking for?', 'dojść do + 生格、idź、skręć、przyを使い、道を尋ねて案内を理解します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'directions', '["cefr:a2","scene:directions","grammar:imperative-and-locative","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czego szukasz","Czego szukasz?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'directions', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l1-i03', 'sentence', 'Szukam poczty przy głównej ulicy.', '大通りにある郵便局を探しています。', 'I am looking for the post office on the main street.', 'dojść do + 生格、idź、skręć、przyを使い、道を尋ねて案内を理解します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'directions', '["cefr:a2","scene:directions","grammar:imperative-and-locative","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Szukam poczty przy głównej ulicy","Szukam poczty przy głównej ulicy."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'directions', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l1-i04', 'sentence', 'Idź prosto, a potem skręć w lewo przy aptece.', 'まっすぐ行き、薬局のところで左に曲がってください。', 'Go straight, then turn left by the pharmacy.', 'dojść do + 生格、idź、skręć、przyを使い、道を尋ねて案内を理解します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'directions', '["cefr:a2","scene:directions","grammar:imperative-and-locative","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Idź prosto, a potem skręć w lewo przy aptece","Idź prosto, a potem skręć w lewo przy aptece."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'directions', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l1-i05', 'sentence', 'Czy to daleko stąd?', 'ここから遠いですか？', 'Is it far from here?', 'dojść do + 生格、idź、skręć、przyを使い、道を尋ねて案内を理解します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'directions', '["cefr:a2","scene:directions","grammar:imperative-and-locative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy to daleko stąd","Czy to daleko stąd?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'directions', 'neutral', 'male', 'learner', 'independent');
