INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u5-l2', 'a2-unit-5', 2, '切符を買う', 'Bilet do Poznania', 'bilet w jedną stronę、na kiedy、z peronuを使い、行き先・時刻・ホームを確認します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l2-i01', 'sentence', 'Poproszę bilet w jedną stronę do Poznania.', 'ポズナンまでの片道切符をお願いします。', 'A one-way ticket to Poznań, please.', 'bilet w jedną stronę、na kiedy、z peronuを使い、行き先・時刻・ホームを確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'transport-ticket', '["cefr:a2","scene:transport-ticket","grammar:genitive-and-ordinal","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Poproszę bilet w jedną stronę do Poznania","Poproszę bilet w jedną stronę do Poznania."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'transport-ticket', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l2-i02', 'sentence', 'Na kiedy potrzebuje pan biletu?', 'いつの切符が必要ですか？', 'For when do you need the ticket?', 'bilet w jedną stronę、na kiedy、z peronuを使い、行き先・時刻・ホームを確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'transport-ticket', '["cefr:a2","scene:transport-ticket","grammar:genitive-and-ordinal","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Na kiedy potrzebuje pan biletu","Na kiedy potrzebuje pan biletu?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'transport-ticket', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l2-i03', 'sentence', 'Na dzisiaj, najlepiej na pociąg o osiemnastej.', '今日の、できれば18時の列車がいいです。', 'For today, preferably the train at six p.m.', 'bilet w jedną stronę、na kiedy、z peronuを使い、行き先・時刻・ホームを確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'transport-ticket', '["cefr:a2","scene:transport-ticket","grammar:genitive-and-ordinal","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Na dzisiaj, najlepiej na pociąg o osiemnastej","Na dzisiaj, najlepiej na pociąg o osiemnastej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'transport-ticket', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l2-i04', 'sentence', 'Ten pociąg odjeżdża z peronu trzeciego.', 'この列車は3番ホームから出ます。', 'This train leaves from platform three.', 'bilet w jedną stronę、na kiedy、z peronuを使い、行き先・時刻・ホームを確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'transport-ticket', '["cefr:a2","scene:transport-ticket","grammar:genitive-and-ordinal","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Ten pociąg odjeżdża z peronu trzeciego","Ten pociąg odjeżdża z peronu trzeciego."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'transport-ticket', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l2-i05', 'sentence', 'Czy muszę kupić miejscówkę?', '座席指定券を買う必要がありますか？', 'Do I have to buy a seat reservation?', 'bilet w jedną stronę、na kiedy、z peronuを使い、行き先・時刻・ホームを確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'transport-ticket', '["cefr:a2","scene:transport-ticket","grammar:genitive-and-ordinal","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy muszę kupić miejscówkę","Czy muszę kupić miejscówkę?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'transport-ticket', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l2-i06', 'sentence', 'Nie, ale warto zająć miejsce wcześniej.', 'いいえ、でも早めに席を取る価値があります。', 'No, but it is worth taking a seat early.', 'bilet w jedną stronę、na kiedy、z peronuを使い、行き先・時刻・ホームを確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'transport-ticket', '["cefr:a2","scene:transport-ticket","grammar:genitive-and-ordinal","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Nie, ale warto zająć miejsce wcześniej","Nie, ale warto zająć miejsce wcześniej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'transport-ticket', 'neutral', 'male', 'partner', 'independent');
