INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l3-i01', 'sentence', 'Pociąg ma opóźnienie czterdziestu minut.', '列車は40分遅れています。', 'The train is delayed by forty minutes.', 'mieć opóźnienie、powinien、zdążyć na、jeśli を使い、遅延と代案を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'travel-delay', '["cefr:a2","scene:travel-delay","grammar:modal-and-future","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Pociąg ma opóźnienie czterdziestu minut","Pociąg ma opóźnienie czterdziestu minut."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'travel-delay', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l3-i02', 'sentence', 'Czy wiadomo, kiedy przyjedzie następny pociąg?', '次の列車がいつ来るか分かりますか？', 'Do you know when the next train will arrive?', 'mieć opóźnienie、powinien、zdążyć na、jeśli を使い、遅延と代案を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'travel-delay', '["cefr:a2","scene:travel-delay","grammar:modal-and-future","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy wiadomo, kiedy przyjedzie następny pociąg","Czy wiadomo, kiedy przyjedzie następny pociąg?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'travel-delay', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l3-i03', 'sentence', 'Według tablicy powinien przyjechać o piętnastej.', '掲示板によると15時に来るはずです。', 'According to the board it should arrive at three p.m.', 'mieć opóźnienie、powinien、zdążyć na、jeśli を使い、遅延と代案を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'travel-delay', '["cefr:a2","scene:travel-delay","grammar:modal-and-future","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Według tablicy powinien przyjechać o piętnastej","Według tablicy powinien przyjechać o piętnastej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'travel-delay', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l3-i04', 'sentence', 'Czy zdążę na przesiadkę?', '乗り換えに間に合いますか？', 'Will I make the connection?', 'mieć opóźnienie、powinien、zdążyć na、jeśli を使い、遅延と代案を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'travel-delay', '["cefr:a2","scene:travel-delay","grammar:modal-and-future","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy zdążę na przesiadkę","Czy zdążę na przesiadkę?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'travel-delay', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l3-i05', 'sentence', 'Jeśli nie, poproszę pracownika o pomoc.', '間に合わなければ、職員に助けを求めます。', 'If not, I will ask an employee for help.', 'mieć opóźnienie、powinien、zdążyć na、jeśli を使い、遅延と代案を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'travel-delay', '["cefr:a2","scene:travel-delay","grammar:modal-and-future","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Jeśli nie, poproszę pracownika o pomoc","Jeśli nie, poproszę pracownika o pomoc."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'travel-delay', 'formal', 'male', 'learner', 'independent');
