INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l4-i01', 'sentence', 'Mam rezerwację na nazwisko Kowalski.', 'コワルスキの名前で予約しています。', 'I have a reservation under the name Kowalski.', 'rezerwacja、na ile nocy、w cenie、przechowaćを使い、ホテルの予約と荷物預けを行います。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'hotel', '["cefr:a2","scene:hotel","grammar:formal-questions","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mam rezerwację na nazwisko Kowalski","Mam rezerwację na nazwisko Kowalski."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'hotel', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l4-i02', 'sentence', 'Na ile nocy państwo zostają?', '何泊お泊まりですか？', 'How many nights are you staying?', 'rezerwacja、na ile nocy、w cenie、przechowaćを使い、ホテルの予約と荷物預けを行います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'hotel', '["cefr:a2","scene:hotel","grammar:formal-questions","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Na ile nocy państwo zostają","Na ile nocy państwo zostają?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'hotel', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l4-i03', 'sentence', 'Zostaję na trzy noce, od piątku do poniedziałku.', '金曜日から月曜日まで3泊します。', 'I am staying for three nights, from Friday to Monday.', 'rezerwacja、na ile nocy、w cenie、przechowaćを使い、ホテルの予約と荷物預けを行います。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'hotel', '["cefr:a2","scene:hotel","grammar:formal-questions","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Zostaję na trzy noce, od piątku do poniedziałku","Zostaję na trzy noce, od piątku do poniedziałku."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'hotel', 'neutral', 'male', 'learner', 'independent');
