INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l4-i06', 'sentence', 'Oczywiście, przechowamy go bez problemu.', 'もちろん、問題なく預かります。', 'Of course, we will store it without a problem.', 'rezerwacja、na ile nocy、w cenie、przechowaćを使い、ホテルの予約と荷物預けを行います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'hotel', '["cefr:a2","scene:hotel","grammar:formal-questions","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Oczywiście, przechowamy go bez problemu","Oczywiście, przechowamy go bez problemu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'hotel', 'informal', 'male', 'partner', 'independent');
