INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u5-l5', 'a2-unit-5', 5, '観光の計画', 'Zwiedzam Kraków', 'chciałbym、najpierw potem、chętnie posłuchamを使い、観光順序と助言を交換します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l5-i01', 'sentence', 'Chciałbym zwiedzić stare miasto i zobaczyć zamek.', '旧市街を観光して城を見たいです。', 'I would like to visit the old town and see the castle.', 'chciałbym、najpierw potem、chętnie posłuchamを使い、観光順序と助言を交換します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'sightseeing', '["cefr:a2","scene:sightseeing","grammar:future-sequence","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym zwiedzić stare miasto i zobaczyć zamek","Chciałbym zwiedzić stare miasto i zobaczyć zamek."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'sightseeing', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l5-i02', 'sentence', 'Co planuje pan zobaczyć w Krakowie?', 'クラクフで何を見る予定ですか？', 'What do you plan to see in Kraków?', 'chciałbym、najpierw potem、chętnie posłuchamを使い、観光順序と助言を交換します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'sightseeing', '["cefr:a2","scene:sightseeing","grammar:future-sequence","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Co planuje pan zobaczyć w Krakowie","Co planuje pan zobaczyć w Krakowie?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'sightseeing', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l5-i03', 'sentence', 'Najpierw pójdę na rynek, a potem do muzeum.', 'まず広場へ行き、そのあと博物館へ行きます。', 'First I will go to the market square, then to the museum.', 'chciałbym、najpierw potem、chętnie posłuchamを使い、観光順序と助言を交換します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'sightseeing', '["cefr:a2","scene:sightseeing","grammar:future-sequence","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Najpierw pójdę na rynek, a potem do muzeum","Najpierw pójdę na rynek, a potem do muzeum."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'sightseeing', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l5-i04', 'sentence', 'Czy ma pan mapę albo aplikację?', '地図かアプリを持っていますか？', 'Do you have a map or an app?', 'chciałbym、najpierw potem、chętnie posłuchamを使い、観光順序と助言を交換します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'sightseeing', '["cefr:a2","scene:sightseeing","grammar:future-sequence","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy ma pan mapę albo aplikację","Czy ma pan mapę albo aplikację?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'sightseeing', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l5-i05', 'sentence', 'Mam mapę w telefonie, ale chętnie posłucham rady.', '携帯に地図がありますが、ぜひ助言を聞きたいです。', 'I have a map on my phone, but I would gladly hear your advice.', 'chciałbym、najpierw potem、chętnie posłuchamを使い、観光順序と助言を交換します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'sightseeing', '["cefr:a2","scene:sightseeing","grammar:future-sequence","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mam mapę w telefonie, ale chętnie posłucham rady","Mam mapę w telefonie, ale chętnie posłucham rady."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'sightseeing', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l5-i06', 'sentence', 'Warto też przejść się nad rzekę wieczorem.', '夕方には川沿いも歩く価値があります。', 'It is also worth walking to the river in the evening.', 'chciałbym、najpierw potem、chętnie posłuchamを使い、観光順序と助言を交換します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'sightseeing', '["cefr:a2","scene:sightseeing","grammar:future-sequence","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Warto też przejść się nad rzekę wieczorem","Warto też przejść się nad rzekę wieczorem."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'sightseeing', 'neutral', 'male', 'partner', 'independent');
