INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u5-l6', 'a2-unit-5', 6, '荷物が届かない', 'Zaginiony bagaż', 'nie przyjechał、jak wygląda、z + 造格、numer zgłoszeniaを使い、荷物の特徴と申告番号を伝えます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u5-l6-i01', 'sentence', 'Mój bagaż nie przyjechał na taśmie.', '私の荷物がターンテーブルに出てきませんでした。', 'My luggage did not arrive on the belt.', 'nie przyjechał、jak wygląda、z + 造格、numer zgłoszeniaを使い、荷物の特徴と申告番号を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'lost-luggage', '["cefr:a2","scene:lost-luggage","grammar:descriptive-genitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mój bagaż nie przyjechał na taśmie","Mój bagaż nie przyjechał na taśmie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'lost-luggage', 'neutral', 'male', 'learner', 'independent');
