INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u6-l1', 'a2-unit-6', 1, '住まいの条件を伝える', 'Szukam mieszkania', 'szukać + 生格、dla + 生格、z balkonemを使い、希望する住居条件を伝えます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l1-i01', 'sentence', 'Szukam małego mieszkania blisko centrum.', '中心部に近い小さなアパートを探しています。', 'I am looking for a small flat near the centre.', 'szukać + 生格、dla + 生格、z balkonemを使い、希望する住居条件を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'housing-search', '["cefr:a2","scene:housing-search","grammar:genitive-and-locative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Szukam małego mieszkania blisko centrum","Szukam małego mieszkania blisko centrum."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'housing-search', 'neutral', 'male', 'learner', 'independent');
