INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l1-i05', 'sentence', 'Nie mam zwierząt, ale chciałbym mieć dużo światła.', 'ペットはいませんが、明るい部屋がいいです。', 'I do not have pets, but I would like plenty of light.', 'szukać + 生格、dla + 生格、z balkonemを使い、希望する住居条件を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'housing-search', '["cefr:a2","scene:housing-search","grammar:genitive-and-locative","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Nie mam zwierząt, ale chciałbym mieć dużo światła","Nie mam zwierząt, ale chciałbym mieć dużo światła."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'housing-search', 'informal', 'male', 'learner', 'independent');
