INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l4-i01', 'sentence', 'Chciałbym zapytać o wysokość czynszu.', '家賃の金額について尋ねたいです。', 'I would like to ask about the amount of rent.', 'wynosić、media、osobno、przed podpisaniemを使い、家賃と契約条件を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'rental-contract', '["cefr:a2","scene:rental-contract","grammar:genitive-and-passive","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym zapytać o wysokość czynszu","Chciałbym zapytać o wysokość czynszu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'rental-contract', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l4-i02', 'sentence', 'Czynsz wynosi trzy tysiące złotych miesięcznie.', '家賃は月3000ズウォティです。', 'The rent is three thousand zlotys per month.', 'wynosić、media、osobno、przed podpisaniemを使い、家賃と契約条件を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'rental-contract', '["cefr:a2","scene:rental-contract","grammar:genitive-and-passive","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czynsz wynosi trzy tysiące złotych miesięcznie","Czynsz wynosi trzy tysiące złotych miesięcznie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'rental-contract', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l4-i03', 'sentence', 'Czy w tej kwocie są już media?', 'この金額に光熱費は含まれていますか？', 'Are utilities already included in this amount?', 'wynosić、media、osobno、przed podpisaniemを使い、家賃と契約条件を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'rental-contract', '["cefr:a2","scene:rental-contract","grammar:genitive-and-passive","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy w tej kwocie są już media","Czy w tej kwocie są już media?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'rental-contract', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l4-i04', 'sentence', 'Prąd i ogrzewanie płaci się osobno.', '電気と暖房は別に支払います。', 'Electricity and heating are paid separately.', 'wynosić、media、osobno、przed podpisaniemを使い、家賃と契約条件を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'rental-contract', '["cefr:a2","scene:rental-contract","grammar:genitive-and-passive","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Prąd i ogrzewanie płaci się osobno","Prąd i ogrzewanie płaci się osobno."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'rental-contract', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l4-i05', 'sentence', 'Czy mogę zobaczyć umowę przed podpisaniem?', '署名前に契約書を見られますか？', 'Can I see the contract before signing?', 'wynosić、media、osobno、przed podpisaniemを使い、家賃と契約条件を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'rental-contract', '["cefr:a2","scene:rental-contract","grammar:genitive-and-passive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy mogę zobaczyć umowę przed podpisaniem","Czy mogę zobaczyć umowę przed podpisaniem?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'rental-contract', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l4-i06', 'sentence', 'Oczywiście, prześlę ją panu e-mailem.', 'もちろん、メールでお送りします。', 'Of course, I will send it to you by email.', 'wynosić、media、osobno、przed podpisaniemを使い、家賃と契約条件を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'rental-contract', '["cefr:a2","scene:rental-contract","grammar:genitive-and-passive","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Oczywiście, prześlę ją panu e-mailem","Oczywiście, prześlę ją panu e-mailem."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'rental-contract', 'formal', 'male', 'partner', 'independent');
