INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u6-l5', 'a2-unit-6', 5, '引っ越しを調整する', 'Przeprowadzka', 'wprowadzać się、przydać się、firma przyjedzieを使い、引っ越しの希望と必要な助けを調整します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l5-i01', 'sentence', 'Wprowadzam się do nowego mieszkania w przyszłym tygodniu.', '来週、新しいアパートに引っ越します。', 'I am moving into a new flat next week.', 'wprowadzać się、przydać się、firma przyjedzieを使い、引っ越しの希望と必要な助けを調整します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'moving', '["cefr:a2","scene:moving","grammar:future-and-dative","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Wprowadzam się do nowego mieszkania w przyszłym tygodniu","Wprowadzam się do nowego mieszkania w przyszłym tygodniu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'moving', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l5-i02', 'sentence', 'Czy potrzebuje pan pomocy z przeprowadzką?', '引っ越しの手伝いが必要ですか？', 'Do you need help with the move?', 'wprowadzać się、przydać się、firma przyjedzieを使い、引っ越しの希望と必要な助けを調整します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'moving', '["cefr:a2","scene:moving","grammar:future-and-dative","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy potrzebuje pan pomocy z przeprowadzką","Czy potrzebuje pan pomocy z przeprowadzką?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'moving', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l5-i03', 'sentence', 'Tak, szczególnie z ciężkimi pudełkami.', 'はい、特に重い箱について助けが必要です。', 'Yes, especially with the heavy boxes.', 'wprowadzać się、przydać się、firma przyjedzieを使い、引っ越しの希望と必要な助けを調整します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'moving', '["cefr:a2","scene:moving","grammar:future-and-dative","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tak, szczególnie z ciężkimi pudełkami","Tak, szczególnie z ciężkimi pudełkami."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'moving', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l5-i04', 'sentence', 'Kiedy przyjedzie firma transportowa?', '運送会社はいつ来ますか？', 'When will the transport company arrive?', 'wprowadzać się、przydać się、firma przyjedzieを使い、引っ越しの希望と必要な助けを調整します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'moving', '["cefr:a2","scene:moving","grammar:future-and-dative","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Kiedy przyjedzie firma transportowa","Kiedy przyjedzie firma transportowa?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'moving', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l5-i05', 'sentence', 'Przyjedzie w środę rano.', '水曜日の朝に来ます。', 'It will arrive on Wednesday morning.', 'wprowadzać się、przydać się、firma przyjedzieを使い、引っ越しの希望と必要な助けを調整します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'moving', '["cefr:a2","scene:moving","grammar:future-and-dative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Przyjedzie w środę rano","Przyjedzie w środę rano."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'moving', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l5-i06', 'sentence', 'W takim razie przygotuję wejście i windę.', 'それなら入口とエレベーターを準備します。', 'In that case I will prepare the entrance and lift.', 'wprowadzać się、przydać się、firma przyjedzieを使い、引っ越しの希望と必要な助けを調整します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'moving', '["cefr:a2","scene:moving","grammar:future-and-dative","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["W takim razie przygotuję wejście i windę","W takim razie przygotuję wejście i windę."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'moving', 'informal', 'male', 'partner', 'independent');
