INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u6-l6', 'a2-unit-6', 6, '鍵をなくしたとき', 'Zgubione klucze', 'zgubić、u właściciela、proszę zadzwonić、jeśli trzebaを使い、鍵の紛失と解決策を伝えます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l6-i01', 'sentence', 'Zgubiłem klucze i nie mogę wejść do domu.', '鍵をなくして家に入れません。', 'I lost my keys and cannot enter the house.', 'zgubić、u właściciela、proszę zadzwonić、jeśli trzebaを使い、鍵の紛失と解決策を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'home-trouble', '["cefr:a2","scene:home-trouble","grammar:genitive-and-if","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Zgubiłem klucze i nie mogę wejść do domu","Zgubiłem klucze i nie mogę wejść do domu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'home-trouble', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l6-i02', 'sentence', 'Czy ma pan zapasowy komplet?', '予備の鍵を持っていますか？', 'Do you have a spare set?', 'zgubić、u właściciela、proszę zadzwonić、jeśli trzebaを使い、鍵の紛失と解決策を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'home-trouble', '["cefr:a2","scene:home-trouble","grammar:genitive-and-if","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy ma pan zapasowy komplet","Czy ma pan zapasowy komplet?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'home-trouble', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l6-i03', 'sentence', 'Nie, zapasowe klucze są u właściciela.', 'いいえ、予備の鍵は大家が持っています。', 'No, the spare keys are with the landlord.', 'zgubić、u właściciela、proszę zadzwonić、jeśli trzebaを使い、鍵の紛失と解決策を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'home-trouble', '["cefr:a2","scene:home-trouble","grammar:genitive-and-if","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Nie, zapasowe klucze są u właściciela","Nie, zapasowe klucze są u właściciela."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'home-trouble', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l6-i04', 'sentence', 'Proszę zadzwonić do niego i wyjaśnić sytuację.', '大家に電話して状況を説明してください。', 'Please call him and explain the situation.', 'zgubić、u właściciela、proszę zadzwonić、jeśli trzebaを使い、鍵の紛失と解決策を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'home-trouble', '["cefr:a2","scene:home-trouble","grammar:genitive-and-if","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Proszę zadzwonić do niego i wyjaśnić sytuację","Proszę zadzwonić do niego i wyjaśnić sytuację."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'home-trouble', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l6-i05', 'sentence', 'Już dzwonię, mam jego numer.', '今電話します、番号を持っています。', 'I am calling now, I have his number.', 'zgubić、u właściciela、proszę zadzwonić、jeśli trzebaを使い、鍵の紛失と解決策を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'home-trouble', '["cefr:a2","scene:home-trouble","grammar:genitive-and-if","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Już dzwonię, mam jego numer","Już dzwonię, mam jego numer."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'home-trouble', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u6-l6-i06', 'sentence', 'Jeśli trzeba, możemy otworzyć drzwi ślusarzem.', '必要なら鍵屋でドアを開けられます。', 'If necessary, we can open the door with a locksmith.', 'zgubić、u właściciela、proszę zadzwonić、jeśli trzebaを使い、鍵の紛失と解決策を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'home-trouble', '["cefr:a2","scene:home-trouble","grammar:genitive-and-if","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jeśli trzeba, możemy otworzyć drzwi ślusarzem","Jeśli trzeba, możemy otworzyć drzwi ślusarzem."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'home-trouble', 'neutral', 'male', 'partner', 'independent');
