INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u7-l1', 'a2-unit-7', 1, '仕事を説明する', 'Moja praca', 'pracować jako、zajmować się、kontaktować się zを使い、職種と業務を説明します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l1-i01', 'sentence', 'Pracuję w małej firmie zajmującej się oprogramowaniem.', 'ソフトウェアを扱う小さな会社で働いています。', 'I work in a small software company.', 'pracować jako、zajmować się、kontaktować się zを使い、職種と業務を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'work', '["cefr:a2","scene:work","grammar:instrumental-and-relative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Pracuję w małej firmie zajmującej się oprogramowaniem","Pracuję w małej firmie zajmującej się oprogramowaniem."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'work', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l1-i02', 'sentence', 'Czym zajmuje się pańska firma?', 'あなたの会社は何を扱っていますか？', 'What does your company do?', 'pracować jako、zajmować się、kontaktować się zを使い、職種と業務を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'work', '["cefr:a2","scene:work","grammar:instrumental-and-relative","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czym zajmuje się pańska firma","Czym zajmuje się pańska firma?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'work', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l1-i03', 'sentence', 'Tworzę dokumentację i kontaktuję się z klientami.', '文書を作り、顧客と連絡を取ります。', 'I create documentation and contact clients.', 'pracować jako、zajmować się、kontaktować się zを使い、職種と業務を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'work', '["cefr:a2","scene:work","grammar:instrumental-and-relative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tworzę dokumentację i kontaktuję się z klientami","Tworzę dokumentację i kontaktuję się z klientami."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'work', 'neutral', 'male', 'learner', 'independent');
