INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l2-i01', 'sentence', 'Dzisiaj muszę przygotować raport dla zespołu.', '今日はチームのために報告書を準備しなければなりません。', 'Today I have to prepare a report for the team.', 'musieć、przesunąć termin、dodatkowego czasuを使い、仕事の依頼と期限変更を行います。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'work-tasks', '["cefr:a2","scene:work-tasks","grammar:modal-and-dative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Dzisiaj muszę przygotować raport dla zespołu","Dzisiaj muszę przygotować raport dla zespołu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'work-tasks', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l2-i02', 'sentence', 'Co musi pani zrobić przed spotkaniem?', '会議の前に何をしなければなりませんか？', 'What do you have to do before the meeting?', 'musieć、przesunąć termin、dodatkowego czasuを使い、仕事の依頼と期限変更を行います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'work-tasks', '["cefr:a2","scene:work-tasks","grammar:modal-and-dative","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Co musi pani zrobić przed spotkaniem","Co musi pani zrobić przed spotkaniem?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'work-tasks', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l2-i03', 'sentence', 'Muszę sprawdzić dane i wysłać podsumowanie.', 'データを確認して、まとめを送らなければなりません。', 'I have to check the data and send a summary.', 'musieć、przesunąć termin、dodatkowego czasuを使い、仕事の依頼と期限変更を行います。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'work-tasks', '["cefr:a2","scene:work-tasks","grammar:modal-and-dative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Muszę sprawdzić dane i wysłać podsumowanie","Muszę sprawdzić dane i wysłać podsumowanie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'work-tasks', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l2-i04', 'sentence', 'Czy potrzebuje pani dodatkowego czasu?', '追加の時間が必要ですか？', 'Do you need extra time?', 'musieć、przesunąć termin、dodatkowego czasuを使い、仕事の依頼と期限変更を行います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'work-tasks', '["cefr:a2","scene:work-tasks","grammar:modal-and-dative","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy potrzebuje pani dodatkowego czasu","Czy potrzebuje pani dodatkowego czasu?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'work-tasks', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l2-i05', 'sentence', 'Tak, czy możemy przesunąć termin do jutra?', 'はい、期限を明日まで延ばせますか？', 'Yes, can we move the deadline to tomorrow?', 'musieć、przesunąć termin、dodatkowego czasuを使い、仕事の依頼と期限変更を行います。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'work-tasks', '["cefr:a2","scene:work-tasks","grammar:modal-and-dative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tak, czy możemy przesunąć termin do jutra","Tak, czy możemy przesunąć termin do jutra?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'work-tasks', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l2-i06', 'sentence', 'Oczywiście, ustalmy nowy termin.', 'もちろん、新しい期限を決めましょう。', 'Of course, let us set a new deadline.', 'musieć、przesunąć termin、dodatkowego czasuを使い、仕事の依頼と期限変更を行います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'work-tasks', '["cefr:a2","scene:work-tasks","grammar:modal-and-dative","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Oczywiście, ustalmy nowy termin","Oczywiście, ustalmy nowy termin."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'work-tasks', 'informal', 'male', 'partner', 'independent');
