INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u7-l3', 'a2-unit-7', 3, '電話で予約を変更する', 'Zmiana wizyty', 'dzwonić w sprawie、przełożyć na、pasowaćを使い、電話で予約の変更を丁寧に行います。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l3-i01', 'sentence', 'Dzień dobry, dzwonię w sprawie wizyty.', 'こんにちは、予約の件で電話しています。', 'Good morning, I am calling about an appointment.', 'dzwonić w sprawie、przełożyć na、pasowaćを使い、電話で予約の変更を丁寧に行います。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'phone-appointment', '["cefr:a2","scene:phone-appointment","grammar:formal-phone","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Dzień dobry, dzwonię w sprawie wizyty","Dzień dobry, dzwonię w sprawie wizyty."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'phone-appointment', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l3-i02', 'sentence', 'W czym mogę pomóc?', 'どうお手伝いできますか？', 'How can I help?', 'dzwonić w sprawie、przełożyć na、pasowaćを使い、電話で予約の変更を丁寧に行います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'phone-appointment', '["cefr:a2","scene:phone-appointment","grammar:formal-phone","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["W czym mogę pomóc","W czym mogę pomóc?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'phone-appointment', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l3-i03', 'sentence', 'Chciałbym przełożyć wizytę na przyszły tydzień.', '予約を来週に変更したいです。', 'I would like to move the appointment to next week.', 'dzwonić w sprawie、przełożyć na、pasowaćを使い、電話で予約の変更を丁寧に行います。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'phone-appointment', '["cefr:a2","scene:phone-appointment","grammar:formal-phone","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym przełożyć wizytę na przyszły tydzień","Chciałbym przełożyć wizytę na przyszły tydzień."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'phone-appointment', 'informal', 'male', 'learner', 'independent');
