INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l3-i05', 'sentence', 'Czy pasuje środa po południu?', '水曜の午後は都合がよいですか？', 'Would Wednesday afternoon suit you?', 'dzwonić w sprawie、przełożyć na、pasowaćを使い、電話で予約の変更を丁寧に行います。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'phone-appointment', '["cefr:a2","scene:phone-appointment","grammar:formal-phone","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy pasuje środa po południu","Czy pasuje środa po południu?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'phone-appointment', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l3-i06', 'sentence', 'Tak, mam wolny termin w środę o piętnastej.', 'はい、水曜日の15時に空きがあります。', 'Yes, I have an available slot on Wednesday at three.', 'dzwonić w sprawie、przełożyć na、pasowaćを使い、電話で予約の変更を丁寧に行います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'phone-appointment', '["cefr:a2","scene:phone-appointment","grammar:formal-phone","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Tak, mam wolny termin w środę o piętnastej","Tak, mam wolny termin w środę o piętnastej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'phone-appointment', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u7-l3-s1', 'a2-u7-l3', 1, 'choice', 'a2-u7-l3-i01', '「こんにちは、予約の件で電話しています。」に合うポーランド語を選びましょう。', 'dzwonić w sprawie、przełożyć na、pasowaćを使い、電話で予約の変更を丁寧に行います。', '[{"value":"Dzień dobry, dzwonię w sprawie wizyty.","label":"Dzień dobry, dzwonię w sprawie wizyty."},{"value":"Chciałbym przełożyć wizytę na przyszły tydzień.","label":"Chciałbym przełożyć wizytę na przyszły tydzień."},{"value":"Czy pasuje środa po południu?","label":"Czy pasuje środa po południu?"},{"value":"Tak, mam wolny termin w środę o piętnastej.","label":"Tak, mam wolny termin w środę o piętnastej."}]', 'multiple_choice', 'meaning_to_polish', 'Dzień dobry, dzwonię w sprawie wizyty.', '', '', '', '[]', 0, '意味から形を認識する');
