INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u7-l4', 'a2-unit-7', 4, '聞き返しと綴り', 'Rozmowa telefoniczna', 'nie słyszę、powtórzyć、przeliterowaćを使い、電話で聞き返し、名前を綴ります。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l4-i01', 'sentence', 'Nie słyszę pana dobrze, czy może pan powtórzyć?', 'よく聞こえません、もう一度言っていただけますか？', 'I cannot hear you well, could you repeat?', 'nie słyszę、powtórzyć、przeliterowaćを使い、電話で聞き返し、名前を綴ります。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'phone-clarification', '["cefr:a2","scene:phone-clarification","grammar:imperative-and-spelling","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Nie słyszę pana dobrze, czy może pan powtórzyć","Nie słyszę pana dobrze, czy może pan powtórzyć?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'phone-clarification', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l4-i02', 'sentence', 'Oczywiście, mówię trochę wolniej.', 'もちろん、少しゆっくり話します。', 'Of course, I will speak a little more slowly.', 'nie słyszę、powtórzyć、przeliterowaćを使い、電話で聞き返し、名前を綴ります。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'phone-clarification', '["cefr:a2","scene:phone-clarification","grammar:imperative-and-spelling","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Oczywiście, mówię trochę wolniej","Oczywiście, mówię trochę wolniej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'phone-clarification', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l4-i03', 'sentence', 'Czy może pan przeliterować swoje nazwisko?', '名字を綴っていただけますか？', 'Could you spell your surname?', 'nie słyszę、powtórzyć、przeliterowaćを使い、電話で聞き返し、名前を綴ります。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'phone-clarification', '["cefr:a2","scene:phone-clarification","grammar:imperative-and-spelling","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy może pan przeliterować swoje nazwisko","Czy może pan przeliterować swoje nazwisko?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'phone-clarification', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l4-i04', 'sentence', 'Kowalski: K-O-W-A-L-S-K-I.', 'コワルスキ、K-O-W-A-L-S-K-Iです。', 'Kowalski: K-O-W-A-L-S-K-I.', 'nie słyszę、powtórzyć、przeliterowaćを使い、電話で聞き返し、名前を綴ります。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'phone-clarification', '["cefr:a2","scene:phone-clarification","grammar:imperative-and-spelling","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Kowalski: K-O-W-A-L-S-K-I","Kowalski: K-O-W-A-L-S-K-I."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'phone-clarification', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l4-i05', 'sentence', 'Dziękuję, oddzwonię po sprawdzeniu danych.', 'ありがとう、情報を確認したら折り返します。', 'Thank you, I will call back after checking the data.', 'nie słyszę、powtórzyć、przeliterowaćを使い、電話で聞き返し、名前を綴ります。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'phone-clarification', '["cefr:a2","scene:phone-clarification","grammar:imperative-and-spelling","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Dziękuję, oddzwonię po sprawdzeniu danych","Dziękuję, oddzwonię po sprawdzeniu danych."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'phone-clarification', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l4-i06', 'sentence', 'W porządku, czekam na telefon.', '分かりました、電話をお待ちしています。', 'All right, I will wait for the call.', 'nie słyszę、powtórzyć、przeliterowaćを使い、電話で聞き返し、名前を綴ります。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'phone-clarification', '["cefr:a2","scene:phone-clarification","grammar:imperative-and-spelling","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["W porządku, czekam na telefon","W porządku, czekam na telefon."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'phone-clarification', 'neutral', 'male', 'partner', 'independent');
