INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u7-l5', 'a2-unit-7', 5, '仕事の予定をメールで確認する', 'Potwierdzenie spotkania', 'żeby potwierdzić、moglibyśmy、dogodna godzinaを使い、丁寧に会議の詳細を確認します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l5-i01', 'sentence', 'Piszę, żeby potwierdzić nasze spotkanie.', '打ち合わせを確認するために書いています。', 'I am writing to confirm our meeting.', 'żeby potwierdzić、moglibyśmy、dogodna godzinaを使い、丁寧に会議の詳細を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'work-email', '["cefr:a2","scene:work-email","grammar:conditional-formal","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Piszę, żeby potwierdzić nasze spotkanie","Piszę, żeby potwierdzić nasze spotkanie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'work-email', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l5-i02', 'sentence', 'Dziękuję za wiadomość i potwierdzam termin.', 'ご連絡ありがとうございます、予定を確認します。', 'Thank you for the message; I confirm the date.', 'żeby potwierdzić、moglibyśmy、dogodna godzinaを使い、丁寧に会議の詳細を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'work-email', '["cefr:a2","scene:work-email","grammar:conditional-formal","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Dziękuję za wiadomość i potwierdzam termin","Dziękuję za wiadomość i potwierdzam termin."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'work-email', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l5-i03', 'sentence', 'Czy moglibyśmy omówić szczegóły przez telefon?', '詳細を電話で話せますか？', 'Could we discuss the details by phone?', 'żeby potwierdzić、moglibyśmy、dogodna godzinaを使い、丁寧に会議の詳細を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'work-email', '["cefr:a2","scene:work-email","grammar:conditional-formal","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy moglibyśmy omówić szczegóły przez telefon","Czy moglibyśmy omówić szczegóły przez telefon?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'work-email', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l5-i04', 'sentence', 'Tak, proszę zaproponować dogodną godzinę.', 'はい、都合のよい時間を提案してください。', 'Yes, please suggest a convenient time.', 'żeby potwierdzić、moglibyśmy、dogodna godzinaを使い、丁寧に会議の詳細を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'work-email', '["cefr:a2","scene:work-email","grammar:conditional-formal","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Tak, proszę zaproponować dogodną godzinę","Tak, proszę zaproponować dogodną godzinę."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'work-email', 'formal', 'male', 'partner', 'independent');
