INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l6-i01', 'sentence', 'Chciałbym umówić wizytę u dentysty.', '歯医者の予約を取りたいです。', 'I would like to make a dentist appointment.', 'umówić wizytę、boleć、po lewej stronieを使い、症状と予約可能な時間を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'medical-appointment', '["cefr:a2","scene:medical-appointment","grammar:dative-and-body","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym umówić wizytę u dentysty","Chciałbym umówić wizytę u dentysty."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'medical-appointment', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l6-i02', 'sentence', 'Czy to pierwsza wizyta w naszej przychodni?', '当院は初めてですか？', 'Is this your first visit to our clinic?', 'umówić wizytę、boleć、po lewej stronieを使い、症状と予約可能な時間を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'medical-appointment', '["cefr:a2","scene:medical-appointment","grammar:dative-and-body","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy to pierwsza wizyta w naszej przychodni","Czy to pierwsza wizyta w naszej przychodni?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'medical-appointment', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u7-l6-i03', 'sentence', 'Tak, boli mnie ząb po lewej stronie.', 'はい、左側の歯が痛いです。', 'Yes, a tooth on my left side hurts.', 'umówić wizytę、boleć、po lewej stronieを使い、症状と予約可能な時間を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'medical-appointment', '["cefr:a2","scene:medical-appointment","grammar:dative-and-body","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tak, boli mnie ząb po lewej stronie","Tak, boli mnie ząb po lewej stronie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'medical-appointment', 'neutral', 'male', 'learner', 'independent');
