INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l1-i01', 'sentence', 'Poproszę pół kilo pomidorów i bochenek chleba.', 'トマトを半キロとパンを1斤ください。', 'Half a kilo of tomatoes and a loaf of bread, please.', '半量・単位名詞、対格、życzyć sobieを使い、量と追加注文を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'market', '["cefr:a2","scene:market","grammar:accusative-measures","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Poproszę pół kilo pomidorów i bochenek chleba","Poproszę pół kilo pomidorów i bochenek chleba."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'market', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l1-i02', 'sentence', 'Czy życzy pan sobie coś jeszcze?', 'ほかにも何かいかがですか？', 'Would you like anything else?', '半量・単位名詞、対格、życzyć sobieを使い、量と追加注文を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'market', '["cefr:a2","scene:market","grammar:accusative-measures","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy życzy pan sobie coś jeszcze","Czy życzy pan sobie coś jeszcze?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'market', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l1-i03', 'sentence', 'Tak, proszę dodać sześć jajek.', 'はい、卵を6個追加してください。', 'Yes, please add six eggs.', '半量・単位名詞、対格、życzyć sobieを使い、量と追加注文を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'market', '["cefr:a2","scene:market","grammar:accusative-measures","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tak, proszę dodać sześć jajek","Tak, proszę dodać sześć jajek."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'market', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l1-i04', 'sentence', 'Ile kosztuje ten ser?', 'このチーズはいくらですか？', 'How much does this cheese cost?', '半量・単位名詞、対格、życzyć sobieを使い、量と追加注文を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'market', '["cefr:a2","scene:market","grammar:accusative-measures","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Ile kosztuje ten ser","Ile kosztuje ten ser?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'market', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l1-i05', 'sentence', 'Ten ser kosztuje trzydzieści złotych za kilogram.', 'このチーズは1キロ30ズウォティです。', 'This cheese costs thirty zlotys per kilogram.', '半量・単位名詞、対格、życzyć sobieを使い、量と追加注文を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'market', '["cefr:a2","scene:market","grammar:accusative-measures","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Ten ser kosztuje trzydzieści złotych za kilogram","Ten ser kosztuje trzydzieści złotych za kilogram."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'market', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l1-i06', 'sentence', 'Dziękuję, to wszystko.', 'ありがとう、以上です。', 'Thank you, that is all.', '半量・単位名詞、対格、życzyć sobieを使い、量と追加注文を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'market', '["cefr:a2","scene:market","grammar:accusative-measures","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Dziękuję, to wszystko","Dziękuję, to wszystko."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'market', 'neutral', 'male', 'partner', 'independent');
