INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l2-i03', 'sentence', 'Najchętniej granatowy, jeśli jest dostępny.', 'あれば、紺色が一番いいです。', 'Preferably navy, if it is available.', 'rozmiar、dostępny、za krótki、zamówićを使い、試着とサイズ変更を依頼します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'clothing', '["cefr:a2","scene:clothing","grammar:comparative-and-case","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Najchętniej granatowy, jeśli jest dostępny","Najchętniej granatowy, jeśli jest dostępny."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'clothing', 'neutral', 'male', 'learner', 'independent');
