INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l3-i04', 'sentence', 'Czy ma pan paragon?', 'レシートをお持ちですか？', 'Do you have the receipt?', 'zwrócić、mimo że、paragon、wymienić albo zwrócićを使い、故障と希望する対応を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'complaint', '["cefr:a2","scene:complaint","grammar:despite-and-perfective","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy ma pan paragon","Czy ma pan paragon?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'complaint', 'formal', 'male', 'partner', 'independent');
