INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l3-i06', 'sentence', 'Wymienimy urządzenie albo zwrócimy pieniądze.', '製品を交換するか、返金します。', 'We will replace the device or refund the money.', 'zwrócić、mimo że、paragon、wymienić albo zwrócićを使い、故障と希望する対応を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'complaint', '["cefr:a2","scene:complaint","grammar:despite-and-perfective","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Wymienimy urządzenie albo zwrócimy pieniądze","Wymienimy urządzenie albo zwrócimy pieniądze."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'complaint', 'informal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u8-l3-s1', 'a2-u8-l3', 1, 'choice', 'a2-u8-l3-i01', '「この壊れた電気ケトルを返品したいです。」に合うポーランド語を選びましょう。', 'zwrócić、mimo że、paragon、wymienić albo zwrócićを使い、故障と希望する対応を説明します。', '[{"value":"Chciałbym zwrócić ten uszkodzony czajnik.","label":"Chciałbym zwrócić ten uszkodzony czajnik."},{"value":"Nie grzeje wody, mimo że jest podłączony.","label":"Nie grzeje wody, mimo że jest podłączony."},{"value":"Tak, tutaj jest paragon i karta gwarancyjna.","label":"Tak, tutaj jest paragon i karta gwarancyjna."},{"value":"Wymienimy urządzenie albo zwrócimy pieniądze.","label":"Wymienimy urządzenie albo zwrócimy pieniądze."}]', 'multiple_choice', 'meaning_to_polish', 'Chciałbym zwrócić ten uszkodzony czajnik.', '', '', '', '[]', 0, '意味から形を認識する');
