INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u8-l4', 'a2-unit-8', 4, 'アレルギーを伝えて注文する', 'Bez orzechów', 'zawierać、bez + 生格、polecaćを使い、アレルギーと代替料理を確認します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l4-i01', 'sentence', 'Czy w tej zupie są orzechy?', 'このスープにナッツは入っていますか？', 'Does this soup contain nuts?', 'zawierać、bez + 生格、polecaćを使い、アレルギーと代替料理を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'restaurant-allergy', '["cefr:a2","scene:restaurant-allergy","grammar:genitive-and-negation","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy w tej zupie są orzechy","Czy w tej zupie są orzechy?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'restaurant-allergy', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l4-i02', 'sentence', 'Nie, ale sos zawiera mleko.', 'いいえ、でもソースには牛乳が入っています。', 'No, but the sauce contains milk.', 'zawierać、bez + 生格、polecaćを使い、アレルギーと代替料理を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'restaurant-allergy', '["cefr:a2","scene:restaurant-allergy","grammar:genitive-and-negation","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Nie, ale sos zawiera mleko","Nie, ale sos zawiera mleko."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'restaurant-allergy', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l4-i03', 'sentence', 'Mam alergię na orzechy, więc poproszę coś bez nich.', 'ナッツアレルギーがあるので、ナッツなしのものをお願いします。', 'I am allergic to nuts, so I would like something without them.', 'zawierać、bez + 生格、polecaćを使い、アレルギーと代替料理を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'restaurant-allergy', '["cefr:a2","scene:restaurant-allergy","grammar:genitive-and-negation","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mam alergię na orzechy, więc poproszę coś bez nich","Mam alergię na orzechy, więc poproszę coś bez nich."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'restaurant-allergy', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l4-i04', 'sentence', 'Co może pani polecić bez mleka?', '牛乳なしで何をおすすめできますか？', 'What can you recommend without milk?', 'zawierać、bez + 生格、polecaćを使い、アレルギーと代替料理を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'restaurant-allergy', '["cefr:a2","scene:restaurant-allergy","grammar:genitive-and-negation","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Co może pani polecić bez mleka","Co może pani polecić bez mleka?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'restaurant-allergy', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l4-i05', 'sentence', 'Polecamy grillowane warzywa z ryżem.', '焼き野菜とご飯をおすすめします。', 'We recommend grilled vegetables with rice.', 'zawierać、bez + 生格、polecaćを使い、アレルギーと代替料理を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'restaurant-allergy', '["cefr:a2","scene:restaurant-allergy","grammar:genitive-and-negation","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Polecamy grillowane warzywa z ryżem","Polecamy grillowane warzywa z ryżem."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'restaurant-allergy', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l4-i06', 'sentence', 'Poproszę warzywa i wodę gazowaną.', '野菜と炭酸水をお願いします。', 'Vegetables and sparkling water, please.', 'zawierać、bez + 生格、polecaćを使い、アレルギーと代替料理を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'restaurant-allergy', '["cefr:a2","scene:restaurant-allergy","grammar:genitive-and-negation","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Poproszę warzywa i wodę gazowaną","Poproszę warzywa i wodę gazowaną."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'restaurant-allergy', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u8-l4-s1', 'a2-u8-l4', 1, 'choice', 'a2-u8-l4-i01', '「このスープにナッツは入っていますか？」に合うポーランド語を選びましょう。', 'zawierać、bez + 生格、polecaćを使い、アレルギーと代替料理を確認します。', '[{"value":"Czy w tej zupie są orzechy?","label":"Czy w tej zupie są orzechy?"},{"value":"Mam alergię na orzechy, więc poproszę coś bez nich.","label":"Mam alergię na orzechy, więc poproszę coś bez nich."},{"value":"Polecamy grillowane warzywa z ryżem.","label":"Polecamy grillowane warzywa z ryżem."},{"value":"Poproszę warzywa i wodę gazowaną.","label":"Poproszę warzywa i wodę gazowaną."}]', 'multiple_choice', 'meaning_to_polish', 'Czy w tej zupie są orzechy?', '', '', '', '[]', 0, '意味から形を認識する');
