INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u8-l5', 'a2-unit-8', 5, '銀行で現金を扱う', 'W banku', 'wypłacić z konta、dokument tożsamości、zapomnieć kodu、resetowaćを使います。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l5-i01', 'sentence', 'Chciałbym wypłacić pieniądze z konta.', '口座からお金を引き出したいです。', 'I would like to withdraw money from my account.', 'wypłacić z konta、dokument tożsamości、zapomnieć kodu、resetowaćを使います。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'bank', '["cefr:a2","scene:bank","grammar:genitive-and-modal","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym wypłacić pieniądze z konta","Chciałbym wypłacić pieniądze z konta."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'bank', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l5-i02', 'sentence', 'Czy ma pan kartę i dokument tożsamości?', 'カードと身分証明書をお持ちですか？', 'Do you have your card and identity document?', 'wypłacić z konta、dokument tożsamości、zapomnieć kodu、resetowaćを使います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'bank', '["cefr:a2","scene:bank","grammar:genitive-and-modal","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy ma pan kartę i dokument tożsamości","Czy ma pan kartę i dokument tożsamości?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'bank', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l5-i03', 'sentence', 'Mam kartę, ale zapomniałem kodu PIN.', 'カードはありますが、PINを忘れました。', 'I have the card, but I forgot the PIN.', 'wypłacić z konta、dokument tożsamości、zapomnieć kodu、resetowaćを使います。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'bank', '["cefr:a2","scene:bank","grammar:genitive-and-modal","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mam kartę, ale zapomniałem kodu PIN","Mam kartę, ale zapomniałem kodu PIN."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'bank', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l5-i04', 'sentence', 'Możemy zresetować kod po sprawdzeniu dokumentu.', '書類を確認したら暗証番号をリセットできます。', 'We can reset the code after checking the document.', 'wypłacić z konta、dokument tożsamości、zapomnieć kodu、resetowaćを使います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'bank', '["cefr:a2","scene:bank","grammar:genitive-and-modal","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Możemy zresetować kod po sprawdzeniu dokumentu","Możemy zresetować kod po sprawdzeniu dokumentu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'bank', 'neutral', 'male', 'partner', 'independent');
