INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l5-i06', 'sentence', 'Tak, terminal obsługuje płatności zbliżeniowe.', 'はい、端末は非接触決済に対応しています。', 'Yes, the terminal supports contactless payments.', 'wypłacić z konta、dokument tożsamości、zapomnieć kodu、resetowaćを使います。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'bank', '["cefr:a2","scene:bank","grammar:genitive-and-modal","register:informal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Tak, terminal obsługuje płatności zbliżeniowe","Tak, terminal obsługuje płatności zbliżeniowe."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'bank', 'informal', 'male', 'partner', 'independent');
