INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u8-l6-i01', 'sentence', 'Chciałbym wysłać paczkę do Niemiec.', 'ドイツへ荷物を送りたいです。', 'I would like to send a parcel to Germany.', 'wysłać do、adres odbiorcy、zabezpieczyć、kosztowaćを使い、宛先・梱包・料金を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'post', '["cefr:a2","scene:post","grammar:address-and-passive","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym wysłać paczkę do Niemiec","Chciałbym wysłać paczkę do Niemiec."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'post', 'informal', 'male', 'learner', 'independent');
