INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u9-l1', 'a2-unit-9', 1, '症状を伝える', 'Objawy', 'boleć mnie、mieć gorączkę、lekki kaszel、uczulony naを使い、症状と服薬情報を伝えます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l1-i01', 'sentence', 'Od dwóch dni boli mnie gardło i mam gorączkę.', '2日前から喉が痛く、熱があります。', 'My throat has hurt and I have had a fever for two days.', 'boleć mnie、mieć gorączkę、lekki kaszel、uczulony naを使い、症状と服薬情報を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'health', '["cefr:a2","scene:health","grammar:body-and-genitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Od dwóch dni boli mnie gardło i mam gorączkę","Od dwóch dni boli mnie gardło i mam gorączkę."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'health', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l1-i02', 'sentence', 'Czy ma pan także kaszel albo katar?', '咳や鼻水もありますか？', 'Do you also have a cough or a runny nose?', 'boleć mnie、mieć gorączkę、lekki kaszel、uczulony naを使い、症状と服薬情報を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'health', '["cefr:a2","scene:health","grammar:body-and-genitive","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy ma pan także kaszel albo katar","Czy ma pan także kaszel albo katar?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'health', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l1-i03', 'sentence', 'Mam lekki kaszel, ale nie mam kataru.', '軽い咳はありますが、鼻水はありません。', 'I have a slight cough, but no runny nose.', 'boleć mnie、mieć gorączkę、lekki kaszel、uczulony naを使い、症状と服薬情報を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'health', '["cefr:a2","scene:health","grammar:body-and-genitive","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mam lekki kaszel, ale nie mam kataru","Mam lekki kaszel, ale nie mam kataru."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'health', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l1-i04', 'sentence', 'Czy jest pan uczulony na jakieś leki?', '薬にアレルギーがありますか？', 'Are you allergic to any medicines?', 'boleć mnie、mieć gorączkę、lekki kaszel、uczulony naを使い、症状と服薬情報を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'health', '["cefr:a2","scene:health","grammar:body-and-genitive","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy jest pan uczulony na jakieś leki","Czy jest pan uczulony na jakieś leki?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'health', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l1-i05', 'sentence', 'Nie jestem uczulony, ale przyjmuję lekarstwo na ciśnienie.', 'アレルギーはありませんが、血圧の薬を飲んでいます。', 'I am not allergic, but I take medicine for blood pressure.', 'boleć mnie、mieć gorączkę、lekki kaszel、uczulony naを使い、症状と服薬情報を伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'health', '["cefr:a2","scene:health","grammar:body-and-genitive","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Nie jestem uczulony, ale przyjmuję lekarstwo na ciśnienie","Nie jestem uczulony, ale przyjmuję lekarstwo na ciśnienie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'health', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l1-i06', 'sentence', 'W takim razie proszę powiedzieć o tym lekarzowi.', 'それなら医師にそのことを伝えてください。', 'In that case, please tell the doctor about it.', 'boleć mnie、mieć gorączkę、lekki kaszel、uczulony naを使い、症状と服薬情報を伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'health', '["cefr:a2","scene:health","grammar:body-and-genitive","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["W takim razie proszę powiedzieć o tym lekarzowi","W takim razie proszę powiedzieć o tym lekarzowi."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'health', 'formal', 'male', 'partner', 'independent');
