INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u9-l1-s2', 'a2-u9-l1', 2, 'choice', 'a2-u9-l1-i01', '「Od dwóch dni boli mnie gardło i mam gorączkę.」の意味を選びましょう。', 'boleć mnie、mieć gorączkę、lekki kaszel、uczulony naを使い、症状と服薬情報を伝えます。', '[{"value":"2日前から喉が痛く、熱があります。","label":"2日前から喉が痛く、熱があります。"},{"value":"軽い咳はありますが、鼻水はありません。","label":"軽い咳はありますが、鼻水はありません。"},{"value":"アレルギーはありませんが、血圧の薬を飲んでいます。","label":"アレルギーはありませんが、血圧の薬を飲んでいます。"},{"value":"それなら医師にそのことを伝えてください。","label":"それなら医師にそのことを伝えてください。"}]', 'multiple_choice', 'polish_to_meaning', '2日前から喉が痛く、熱があります。', '', '', '', '[]', 0, '形から意味を認識する');
