INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u9-l2', 'a2-unit-9', 2, '診察の予約をする', 'W przychodni', 'umówić wizytę、źle się czuć、najlepiej po、co dolegaを使い、予約から症状説明へ進みます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l2-i01', 'sentence', 'Chciałbym umówić wizytę, bo źle się czuję.', '具合が悪いので診察の予約を取りたいです。', 'I would like to make an appointment because I feel unwell.', 'umówić wizytę、źle się czuć、najlepiej po、co dolegaを使い、予約から症状説明へ進みます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'doctor', '["cefr:a2","scene:doctor","grammar:reflexive-and-time","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym umówić wizytę, bo źle się czuję","Chciałbym umówić wizytę, bo źle się czuję."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'doctor', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l2-i02', 'sentence', 'Czy może pan przyjść dzisiaj po południu?', '今日の午後に来られますか？', 'Can you come this afternoon?', 'umówić wizytę、źle się czuć、najlepiej po、co dolegaを使い、予約から症状説明へ進みます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'doctor', '["cefr:a2","scene:doctor","grammar:reflexive-and-time","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy może pan przyjść dzisiaj po południu","Czy może pan przyjść dzisiaj po południu?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'doctor', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l2-i03', 'sentence', 'Tak, najlepiej po siedemnastej.', 'はい、17時以降が一番よいです。', 'Yes, preferably after five.', 'umówić wizytę、źle się czuć、najlepiej po、co dolegaを使い、予約から症状説明へ進みます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'doctor', '["cefr:a2","scene:doctor","grammar:reflexive-and-time","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tak, najlepiej po siedemnastej","Tak, najlepiej po siedemnastej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'doctor', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l2-i04', 'sentence', 'Proszę opisać, co panu dolega.', 'どんな症状があるか説明してください。', 'Please describe what is wrong.', 'umówić wizytę、źle się czuć、najlepiej po、co dolegaを使い、予約から症状説明へ進みます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'doctor', '["cefr:a2","scene:doctor","grammar:reflexive-and-time","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Proszę opisać, co panu dolega","Proszę opisać, co panu dolega."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'doctor', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l2-i05', 'sentence', 'Boli mnie brzuch i od rana mam nudności.', 'お腹が痛く、朝から吐き気があります。', 'My stomach hurts and I have felt nauseous since morning.', 'umówić wizytę、źle się czuć、najlepiej po、co dolegaを使い、予約から症状説明へ進みます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'doctor', '["cefr:a2","scene:doctor","grammar:reflexive-and-time","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Boli mnie brzuch i od rana mam nudności","Boli mnie brzuch i od rana mam nudności."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'doctor', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l2-i06', 'sentence', 'Zbadamy pana i zdecydujemy o leczeniu.', '診察して治療を決めます。', 'We will examine you and decide on treatment.', 'umówić wizytę、źle się czuć、najlepiej po、co dolegaを使い、予約から症状説明へ進みます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'doctor', '["cefr:a2","scene:doctor","grammar:reflexive-and-time","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Zbadamy pana i zdecydujemy o leczeniu","Zbadamy pana i zdecydujemy o leczeniu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'doctor', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u9-l2-s1', 'a2-u9-l2', 1, 'choice', 'a2-u9-l2-i01', '「具合が悪いので診察の予約を取りたいです。」に合うポーランド語を選びましょう。', 'umówić wizytę、źle się czuć、najlepiej po、co dolegaを使い、予約から症状説明へ進みます。', '[{"value":"Chciałbym umówić wizytę, bo źle się czuję.","label":"Chciałbym umówić wizytę, bo źle się czuję."},{"value":"Tak, najlepiej po siedemnastej.","label":"Tak, najlepiej po siedemnastej."},{"value":"Boli mnie brzuch i od rana mam nudności.","label":"Boli mnie brzuch i od rana mam nudności."},{"value":"Zbadamy pana i zdecydujemy o leczeniu.","label":"Zbadamy pana i zdecydujemy o leczeniu."}]', 'multiple_choice', 'meaning_to_polish', 'Chciałbym umówić wizytę, bo źle się czuję.', '', '', '', '[]', 0, '意味から形を認識する');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u9-l2-s2', 'a2-u9-l2', 2, 'choice', 'a2-u9-l2-i01', '「Chciałbym umówić wizytę, bo źle się czuję.」の意味を選びましょう。', 'umówić wizytę、źle się czuć、najlepiej po、co dolegaを使い、予約から症状説明へ進みます。', '[{"value":"具合が悪いので診察の予約を取りたいです。","label":"具合が悪いので診察の予約を取りたいです。"},{"value":"はい、17時以降が一番よいです。","label":"はい、17時以降が一番よいです。"},{"value":"お腹が痛く、朝から吐き気があります。","label":"お腹が痛く、朝から吐き気があります。"},{"value":"診察して治療を決めます。","label":"診察して治療を決めます。"}]', 'multiple_choice', 'polish_to_meaning', '具合が悪いので診察の予約を取りたいです。', '', '', '', '[]', 0, '形から意味を認識する');
