INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u9-l3', 'a2-unit-9', 3, '薬局で薬を買う', 'W aptece', 'na ból、bez recepty、należy przyjmować、łączyć zを使い、薬の種類と用法を確認します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l3-i01', 'sentence', 'Poproszę coś na ból głowy.', '頭痛に効くものをください。', 'Something for a headache, please.', 'na ból、bez recepty、należy przyjmować、łączyć zを使い、薬の種類と用法を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'pharmacy', '["cefr:a2","scene:pharmacy","grammar:modal-and-dosage","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Poproszę coś na ból głowy","Poproszę coś na ból głowy."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'pharmacy', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l3-i02', 'sentence', 'Czy woli pan tabletki czy syrop?', '錠剤とシロップのどちらがよいですか？', 'Do you prefer tablets or syrup?', 'na ból、bez recepty、należy przyjmować、łączyć zを使い、薬の種類と用法を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'pharmacy', '["cefr:a2","scene:pharmacy","grammar:modal-and-dosage","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy woli pan tabletki czy syrop","Czy woli pan tabletki czy syrop?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'pharmacy', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l3-i03', 'sentence', 'Poproszę tabletki, ale bez recepty.', '錠剤を、処方箋なしでお願いします。', 'Tablets, please, but without a prescription.', 'na ból、bez recepty、należy przyjmować、łączyć zを使い、薬の種類と用法を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'pharmacy', '["cefr:a2","scene:pharmacy","grammar:modal-and-dosage","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Poproszę tabletki, ale bez recepty","Poproszę tabletki, ale bez recepty."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'pharmacy', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l3-i04', 'sentence', 'Jak często należy je przyjmować?', 'どのくらいの頻度で服用すべきですか？', 'How often should they be taken?', 'na ból、bez recepty、należy przyjmować、łączyć zを使い、薬の種類と用法を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'pharmacy', '["cefr:a2","scene:pharmacy","grammar:modal-and-dosage","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jak często należy je przyjmować","Jak często należy je przyjmować?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'pharmacy', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l3-i05', 'sentence', 'Proszę przyjmować jedną tabletkę po jedzeniu.', '食後に1錠飲んでください。', 'Please take one tablet after eating.', 'na ból、bez recepty、należy przyjmować、łączyć zを使い、薬の種類と用法を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'pharmacy', '["cefr:a2","scene:pharmacy","grammar:modal-and-dosage","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Proszę przyjmować jedną tabletkę po jedzeniu","Proszę przyjmować jedną tabletkę po jedzeniu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'pharmacy', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l3-i06', 'sentence', 'Czy mogę łączyć ten lek z innymi?', 'この薬を他の薬と一緒に飲めますか？', 'Can I combine this medicine with others?', 'na ból、bez recepty、należy przyjmować、łączyć zを使い、薬の種類と用法を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'pharmacy', '["cefr:a2","scene:pharmacy","grammar:modal-and-dosage","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy mogę łączyć ten lek z innymi","Czy mogę łączyć ten lek z innymi?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'pharmacy', 'neutral', 'male', 'partner', 'independent');
