INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u9-l4', 'a2-unit-9', 4, '医師の指示を理解する', 'Zalecenia lekarza', 'powinienem、proszę unikać、jeśli nadalを使い、指示・条件・経過観察を確認します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l4-i01', 'sentence', 'Jak długo powinienem odpoczywać?', 'どのくらい休むべきですか？', 'How long should I rest?', 'powinienem、proszę unikać、jeśli nadalを使い、指示・条件・経過観察を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'medical-advice', '["cefr:a2","scene:medical-advice","grammar:imperative-and-condition","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Jak długo powinienem odpoczywać","Jak długo powinienem odpoczywać?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'medical-advice', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l4-i02', 'sentence', 'Przez kilka dni proszę unikać wysiłku.', '数日間は運動を避けてください。', 'Please avoid exertion for a few days.', 'powinienem、proszę unikać、jeśli nadalを使い、指示・条件・経過観察を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'medical-advice', '["cefr:a2","scene:medical-advice","grammar:imperative-and-condition","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Przez kilka dni proszę unikać wysiłku","Przez kilka dni proszę unikać wysiłku."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'medical-advice', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l4-i03', 'sentence', 'Czy mogę jutro iść do pracy?', '明日仕事へ行ってもよいですか？', 'Can I go to work tomorrow?', 'powinienem、proszę unikać、jeśli nadalを使い、指示・条件・経過観察を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'medical-advice', '["cefr:a2","scene:medical-advice","grammar:imperative-and-condition","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy mogę jutro iść do pracy","Czy mogę jutro iść do pracy?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'medical-advice', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l4-i04', 'sentence', 'Jeśli nadal będzie gorączka, proszę zostać w domu.', 'まだ熱があれば、家にいてください。', 'If you still have a fever, please stay home.', 'powinienem、proszę unikać、jeśli nadalを使い、指示・条件・経過観察を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'medical-advice', '["cefr:a2","scene:medical-advice","grammar:imperative-and-condition","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jeśli nadal będzie gorączka, proszę zostać w domu","Jeśli nadal będzie gorączka, proszę zostać w domu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'medical-advice', 'formal', 'male', 'partner', 'independent');
