INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l4-i06', 'sentence', 'Proszę skontaktować się z lekarzem, jeśli się pogorszą.', '悪化したら医師に連絡してください。', 'Please contact a doctor if they get worse.', 'powinienem、proszę unikać、jeśli nadalを使い、指示・条件・経過観察を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'medical-advice', '["cefr:a2","scene:medical-advice","grammar:imperative-and-condition","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Proszę skontaktować się z lekarzem, jeśli się pogorszą","Proszę skontaktować się z lekarzem, jeśli się pogorszą."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'medical-advice', 'neutral', 'male', 'partner', 'independent');
