INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u9-l5', 'a2-unit-9', 5, '緊急時に助けを求める', 'Nagła sytuacja', 'wezwać、stracić przytomność、oddychać、nie ruszaćを使い、緊急状況を短く正確に伝えます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l5-i01', 'sentence', 'Proszę wezwać karetkę, ktoś zasłabł.', '救急車を呼んでください、誰かが気を失いました。', 'Please call an ambulance, someone fainted.', 'wezwać、stracić przytomność、oddychać、nie ruszaćを使い、緊急状況を短く正確に伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'emergency', '["cefr:a2","scene:emergency","grammar:imperative-and-perfective","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Proszę wezwać karetkę, ktoś zasłabł","Proszę wezwać karetkę, ktoś zasłabł."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'emergency', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l5-i02', 'sentence', 'Co się stało i gdzie państwo jesteście?', '何が起きて、どこにいますか？', 'What happened and where are you?', 'wezwać、stracić przytomność、oddychać、nie ruszaćを使い、緊急状況を短く正確に伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'emergency', '["cefr:a2","scene:emergency","grammar:imperative-and-perfective","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Co się stało i gdzie państwo jesteście","Co się stało i gdzie państwo jesteście?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'emergency', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l5-i03', 'sentence', 'Mężczyzna stracił przytomność przy wejściu do stacji.', '男性が駅の入口で意識を失いました。', 'A man lost consciousness by the station entrance.', 'wezwać、stracić przytomność、oddychać、nie ruszaćを使い、緊急状況を短く正確に伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'emergency', '["cefr:a2","scene:emergency","grammar:imperative-and-perfective","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mężczyzna stracił przytomność przy wejściu do stacji","Mężczyzna stracił przytomność przy wejściu do stacji."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'emergency', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l5-i04', 'sentence', 'Czy oddycha?', '呼吸していますか？', 'Is he breathing?', 'wezwać、stracić przytomność、oddychać、nie ruszaćを使い、緊急状況を短く正確に伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'emergency', '["cefr:a2","scene:emergency","grammar:imperative-and-perfective","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy oddycha","Czy oddycha?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'emergency', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l5-i05', 'sentence', 'Tak, oddycha, ale nie reaguje.', 'はい、呼吸していますが、反応がありません。', 'Yes, he is breathing, but he is not responding.', 'wezwać、stracić przytomność、oddychać、nie ruszaćを使い、緊急状況を短く正確に伝えます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'emergency', '["cefr:a2","scene:emergency","grammar:imperative-and-perfective","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tak, oddycha, ale nie reaguje","Tak, oddycha, ale nie reaguje."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'emergency', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l5-i06', 'sentence', 'Proszę nie ruszać go i czekać na pomoc.', '動かさず、助けを待ってください。', 'Please do not move him and wait for help.', 'wezwać、stracić przytomność、oddychać、nie ruszaćを使い、緊急状況を短く正確に伝えます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'emergency', '["cefr:a2","scene:emergency","grammar:imperative-and-perfective","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Proszę nie ruszać go i czekać na pomoc","Proszę nie ruszać go i czekać na pomoc."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'emergency', 'neutral', 'male', 'partner', 'independent');
