INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u9-l5-s2', 'a2-u9-l5', 2, 'choice', 'a2-u9-l5-i01', '「Proszę wezwać karetkę, ktoś zasłabł.」の意味を選びましょう。', 'wezwać、stracić przytomność、oddychać、nie ruszaćを使い、緊急状況を短く正確に伝えます。', '[{"value":"救急車を呼んでください、誰かが気を失いました。","label":"救急車を呼んでください、誰かが気を失いました。"},{"value":"男性が駅の入口で意識を失いました。","label":"男性が駅の入口で意識を失いました。"},{"value":"はい、呼吸していますが、反応がありません。","label":"はい、呼吸していますが、反応がありません。"},{"value":"動かさず、助けを待ってください。","label":"動かさず、助けを待ってください。"}]', 'multiple_choice', 'polish_to_meaning', '救急車を呼んでください、誰かが気を失いました。', '', '', '', '[]', 0, '形から意味を認識する');
