INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u9-l6', 'a2-unit-9', 6, '心身の状態を相談する', 'Gorszy sen', 'trudno mi、od kilku tygodni、ograniczać、porozmawiaćを使い、長く続く不調と対策を話します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l6-i01', 'sentence', 'Ostatnio trudno mi się skupić i źle sypiam.', '最近、集中しづらく、よく眠れません。', 'Recently I find it hard to concentrate and I sleep badly.', 'trudno mi、od kilku tygodni、ograniczać、porozmawiaćを使い、長く続く不調と対策を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'wellbeing', '["cefr:a2","scene:wellbeing","grammar:reflexive-and-duration","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Ostatnio trudno mi się skupić i źle sypiam","Ostatnio trudno mi się skupić i źle sypiam."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'wellbeing', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l6-i02', 'sentence', 'Od jak dawna ma pan takie problemy?', 'どのくらい前からその問題がありますか？', 'How long have you had these problems?', 'trudno mi、od kilku tygodni、ograniczać、porozmawiaćを使い、長く続く不調と対策を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'wellbeing', '["cefr:a2","scene:wellbeing","grammar:reflexive-and-duration","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Od jak dawna ma pan takie problemy","Od jak dawna ma pan takie problemy?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'wellbeing', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l6-i03', 'sentence', 'Od kilku tygodni, szczególnie kiedy mam dużo pracy.', '数週間前からで、特に仕事が多いときです。', 'For several weeks, especially when I have a lot of work.', 'trudno mi、od kilku tygodni、ograniczać、porozmawiaćを使い、長く続く不調と対策を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'wellbeing', '["cefr:a2","scene:wellbeing","grammar:reflexive-and-duration","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Od kilku tygodni, szczególnie kiedy mam dużo pracy","Od kilku tygodni, szczególnie kiedy mam dużo pracy."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'wellbeing', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l6-i04', 'sentence', 'Czy próbował pan odpoczywać przed snem?', '寝る前に休もうとしてみましたか？', 'Have you tried resting before sleep?', 'trudno mi、od kilku tygodni、ograniczać、porozmawiaćを使い、長く続く不調と対策を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'wellbeing', '["cefr:a2","scene:wellbeing","grammar:reflexive-and-duration","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy próbował pan odpoczywać przed snem","Czy próbował pan odpoczywać przed snem?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'wellbeing', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l6-i05', 'sentence', 'Ograniczam telefon wieczorem i chodzę na spacery.', '夜は携帯を減らし、散歩しています。', 'I limit my phone in the evening and go for walks.', 'trudno mi、od kilku tygodni、ograniczać、porozmawiaćを使い、長く続く不調と対策を話します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'wellbeing', '["cefr:a2","scene:wellbeing","grammar:reflexive-and-duration","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Ograniczam telefon wieczorem i chodzę na spacery","Ograniczam telefon wieczorem i chodzę na spacery."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'wellbeing', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u9-l6-i06', 'sentence', 'To dobry początek, porozmawiajmy o dalszej pomocy.', 'よい始まりです、今後の助けについて話しましょう。', 'That is a good start; let us talk about further help.', 'trudno mi、od kilku tygodni、ograniczać、porozmawiaćを使い、長く続く不調と対策を話します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'wellbeing', '["cefr:a2","scene:wellbeing","grammar:reflexive-and-duration","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["To dobry początek, porozmawiajmy o dalszej pomocy","To dobry początek, porozmawiajmy o dalszej pomocy."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'wellbeing', 'neutral', 'male', 'partner', 'independent');
