INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u9-l6-s2', 'a2-u9-l6', 2, 'choice', 'a2-u9-l6-i01', '「Ostatnio trudno mi się skupić i źle sypiam.」の意味を選びましょう。', 'trudno mi、od kilku tygodni、ograniczać、porozmawiaćを使い、長く続く不調と対策を話します。', '[{"value":"最近、集中しづらく、よく眠れません。","label":"最近、集中しづらく、よく眠れません。"},{"value":"数週間前からで、特に仕事が多いときです。","label":"数週間前からで、特に仕事が多いときです。"},{"value":"夜は携帯を減らし、散歩しています。","label":"夜は携帯を減らし、散歩しています。"},{"value":"よい始まりです、今後の助けについて話しましょう。","label":"よい始まりです、今後の助けについて話しましょう。"}]', 'multiple_choice', 'polish_to_meaning', '最近、集中しづらく、よく眠れません。', '', '', '', '[]', 0, '形から意味を認識する');
