INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l1-i01', 'sentence', 'Chciałbym złożyć wniosek o kartę pobytu.', '滞在カードの申請をしたいです。', 'I would like to submit an application for a residence card.', 'złożyć wniosek o、wymagany、brakuje、naprzeciwkoを使い、役所で書類を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'residence-office', '["cefr:a2","scene:residence-office","grammar:genitive-and-documents","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym złożyć wniosek o kartę pobytu","Chciałbym złożyć wniosek o kartę pobytu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'residence-office', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l1-i02', 'sentence', 'Czy ma pan wszystkie wymagane dokumenty?', '必要な書類はすべてありますか？', 'Do you have all the required documents?', 'złożyć wniosek o、wymagany、brakuje、naprzeciwkoを使い、役所で書類を確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'residence-office', '["cefr:a2","scene:residence-office","grammar:genitive-and-documents","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy ma pan wszystkie wymagane dokumenty","Czy ma pan wszystkie wymagane dokumenty?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'residence-office', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l1-i03', 'sentence', 'Mam paszport, umowę najmu i potwierdzenie ubezpieczenia.', 'パスポート、賃貸契約書、保険の証明があります。', 'I have my passport, rental contract and proof of insurance.', 'złożyć wniosek o、wymagany、brakuje、naprzeciwkoを使い、役所で書類を確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'residence-office', '["cefr:a2","scene:residence-office","grammar:genitive-and-documents","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mam paszport, umowę najmu i potwierdzenie ubezpieczenia","Mam paszport, umowę najmu i potwierdzenie ubezpieczenia."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'residence-office', 'neutral', 'male', 'learner', 'independent');
