INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u10-l2', 'a2-unit-10', 2, '銀行口座を開く', 'Otwieram konto', 'otworzyć konto、formularz、rubryka、wyciąg elektronicznyを使い、銀行のフォームを確認します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l2-i01', 'sentence', 'Chciałbym otworzyć konto bankowe.', '銀行口座を開きたいです。', 'I would like to open a bank account.', 'otworzyć konto、formularz、rubryka、wyciąg elektronicznyを使い、銀行のフォームを確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'bank-formal', '["cefr:a2","scene:bank-formal","grammar:dative-and-formal","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym otworzyć konto bankowe","Chciałbym otworzyć konto bankowe."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'bank-formal', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l2-i02', 'sentence', 'Czy ma pan numer PESEL i dokument tożsamości?', 'PESEL番号と身分証明書をお持ちですか？', 'Do you have a PESEL number and identity document?', 'otworzyć konto、formularz、rubryka、wyciąg elektronicznyを使い、銀行のフォームを確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'bank-formal', '["cefr:a2","scene:bank-formal","grammar:dative-and-formal","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy ma pan numer PESEL i dokument tożsamości","Czy ma pan numer PESEL i dokument tożsamości?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'bank-formal', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l2-i03', 'sentence', 'Mam PESEL, ale potrzebuję pomocy z formularzem.', 'PESELはありますが、フォームの助けが必要です。', 'I have a PESEL, but I need help with the form.', 'otworzyć konto、formularz、rubryka、wyciąg elektronicznyを使い、銀行のフォームを確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'bank-formal', '["cefr:a2","scene:bank-formal","grammar:dative-and-formal","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Mam PESEL, ale potrzebuję pomocy z formularzem","Mam PESEL, ale potrzebuję pomocy z formularzem."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'bank-formal', 'neutral', 'male', 'learner', 'independent');
