INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l2-i05', 'sentence', 'Czy mogę otrzymywać wyciągi elektronicznie?', '電子明細を受け取れますか？', 'Can I receive electronic statements?', 'otworzyć konto、formularz、rubryka、wyciąg elektronicznyを使い、銀行のフォームを確認します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'bank-formal', '["cefr:a2","scene:bank-formal","grammar:dative-and-formal","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Czy mogę otrzymywać wyciągi elektronicznie","Czy mogę otrzymywać wyciągi elektronicznie?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'bank-formal', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l2-i06', 'sentence', 'Tak, włączymy tę usługę od razu.', 'はい、このサービスをすぐに有効にします。', 'Yes, we will activate this service right away.', 'otworzyć konto、formularz、rubryka、wyciąg elektronicznyを使い、銀行のフォームを確認します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'bank-formal', '["cefr:a2","scene:bank-formal","grammar:dative-and-formal","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Tak, włączymy tę usługę od razu","Tak, włączymy tę usługę od razu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'bank-formal', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u10-l2-s1', 'a2-u10-l2', 1, 'choice', 'a2-u10-l2-i01', '「銀行口座を開きたいです。」に合うポーランド語を選びましょう。', 'otworzyć konto、formularz、rubryka、wyciąg elektronicznyを使い、銀行のフォームを確認します。', '[{"value":"Chciałbym otworzyć konto bankowe.","label":"Chciałbym otworzyć konto bankowe."},{"value":"Mam PESEL, ale potrzebuję pomocy z formularzem.","label":"Mam PESEL, ale potrzebuję pomocy z formularzem."},{"value":"Czy mogę otrzymywać wyciągi elektronicznie?","label":"Czy mogę otrzymywać wyciągi elektronicznie?"},{"value":"Tak, włączymy tę usługę od razu.","label":"Tak, włączymy tę usługę od razu."}]', 'multiple_choice', 'meaning_to_polish', 'Chciałbym otworzyć konto bankowe.', '', '', '', '[]', 0, '意味から形を認識する');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u10-l2-s2', 'a2-u10-l2', 2, 'choice', 'a2-u10-l2-i01', '「Chciałbym otworzyć konto bankowe.」の意味を選びましょう。', 'otworzyć konto、formularz、rubryka、wyciąg elektronicznyを使い、銀行のフォームを確認します。', '[{"value":"銀行口座を開きたいです。","label":"銀行口座を開きたいです。"},{"value":"PESELはありますが、フォームの助けが必要です。","label":"PESELはありますが、フォームの助けが必要です。"},{"value":"電子明細を受け取れますか？","label":"電子明細を受け取れますか？"},{"value":"はい、このサービスをすぐに有効にします。","label":"はい、このサービスをすぐに有効にします。"}]', 'multiple_choice', 'polish_to_meaning', '銀行口座を開きたいです。', '', '', '', '[]', 0, '形から意味を認識する');
INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u10-l2-s3', 'a2-u10-l2', 3, 'input', 'a2-u10-l2-i01', '「銀行口座を開きたいです。」の文を完成させましょう。', 'otworzyć konto、formularz、rubryka、wyciąg elektronicznyを使い、銀行のフォームを確認します。', NULL, 'cloze', 'meaning_to_polish', 'konto', 'Chciałbym otworzyć', 'bankowe.', 'konto', '[]', 1, '文の一部を手がかりにする');
