INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u10-l3', 'a2-unit-10', 3, '住所変更を届け出る', 'Zmiana adresu', 'zgłosić zmianę、od kiedy、adres korespondencyjny、wysyłaćを使い、住所と郵便の変更を届け出ます。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l3-i01', 'sentence', 'Chciałbym zgłosić zmianę adresu.', '住所変更を届け出たいです。', 'I would like to report a change of address.', 'zgłosić zmianę、od kiedy、adres korespondencyjny、wysyłaćを使い、住所と郵便の変更を届け出ます。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'official-address', '["cefr:a2","scene:official-address","grammar:locative-and-date","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym zgłosić zmianę adresu","Chciałbym zgłosić zmianę adresu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'official-address', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l3-i02', 'sentence', 'Od kiedy mieszka pan pod nowym adresem?', 'いつから新住所に住んでいますか？', 'Since when have you lived at the new address?', 'zgłosić zmianę、od kiedy、adres korespondencyjny、wysyłaćを使い、住所と郵便の変更を届け出ます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'official-address', '["cefr:a2","scene:official-address","grammar:locative-and-date","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Od kiedy mieszka pan pod nowym adresem","Od kiedy mieszka pan pod nowym adresem?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'official-address', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l3-i03', 'sentence', 'Od pierwszego marca mieszkam przy ulicy Lipowej.', '3月1日からリポワ通りに住んでいます。', 'Since the first of March I have lived on Lipowa Street.', 'zgłosić zmianę、od kiedy、adres korespondencyjny、wysyłaćを使い、住所と郵便の変更を届け出ます。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'official-address', '["cefr:a2","scene:official-address","grammar:locative-and-date","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Od pierwszego marca mieszkam przy ulicy Lipowej","Od pierwszego marca mieszkam przy ulicy Lipowej."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'official-address', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l3-i04', 'sentence', 'Czy chce pan także zmienić adres korespondencyjny?', '郵送先住所も変更しますか？', 'Do you also want to change the correspondence address?', 'zgłosić zmianę、od kiedy、adres korespondencyjny、wysyłaćを使い、住所と郵便の変更を届け出ます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'official-address', '["cefr:a2","scene:official-address","grammar:locative-and-date","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy chce pan także zmienić adres korespondencyjny","Czy chce pan także zmienić adres korespondencyjny?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'official-address', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l3-i05', 'sentence', 'Tak, proszę wysyłać listy na nowy adres.', 'はい、手紙を新住所に送ってください。', 'Yes, please send letters to the new address.', 'zgłosić zmianę、od kiedy、adres korespondencyjny、wysyłaćを使い、住所と郵便の変更を届け出ます。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'official-address', '["cefr:a2","scene:official-address","grammar:locative-and-date","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tak, proszę wysyłać listy na nowy adres","Tak, proszę wysyłać listy na nowy adres."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'official-address', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l3-i06', 'sentence', 'Zapisaliśmy zmianę i wyślemy potwierdzenie.', '変更を記録し、確認を送ります。', 'We recorded the change and will send confirmation.', 'zgłosić zmianę、od kiedy、adres korespondencyjny、wysyłaćを使い、住所と郵便の変更を届け出ます。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'official-address', '["cefr:a2","scene:official-address","grammar:locative-and-date","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Zapisaliśmy zmianę i wyślemy potwierdzenie","Zapisaliśmy zmianę i wyślemy potwierdzenie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'official-address', 'neutral', 'male', 'partner', 'independent');
