INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u10-l4', 'a2-unit-10', 4, '家電の修理を依頼する', 'Naprawa pralki', 'zgłosić problem、gwarancja、usterka、umówić technikaを使い、故障の内容と保証を説明します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l4-i01', 'sentence', 'Chciałbym zgłosić problem z pralką.', '洗濯機の問題を報告したいです。', 'I would like to report a problem with the washing machine.', 'zgłosić problem、gwarancja、usterka、umówić technikaを使い、故障の内容と保証を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはinformal、教材内の学習者は男性話者を想定する。', 'repair', '["cefr:a2","scene:repair","grammar:past-and-relative","register:informal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Chciałbym zgłosić problem z pralką","Chciałbym zgłosić problem z pralką."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'repair', 'informal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l4-i02', 'sentence', 'Czy urządzenie jest jeszcze na gwarancji?', '機器はまだ保証期間内ですか？', 'Is the device still under warranty?', 'zgłosić problem、gwarancja、usterka、umówić technikaを使い、故障の内容と保証を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'repair', '["cefr:a2","scene:repair","grammar:past-and-relative","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy urządzenie jest jeszcze na gwarancji","Czy urządzenie jest jeszcze na gwarancji?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'repair', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l4-i03', 'sentence', 'Tak, kupiłem je sześć miesięcy temu.', 'はい、6か月前に買いました。', 'Yes, I bought it six months ago.', 'zgłosić problem、gwarancja、usterka、umówić technikaを使い、故障の内容と保証を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'repair', '["cefr:a2","scene:repair","grammar:past-and-relative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Tak, kupiłem je sześć miesięcy temu","Tak, kupiłem je sześć miesięcy temu."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'repair', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l4-i04', 'sentence', 'Proszę opisać usterkę.', '故障を説明してください。', 'Please describe the fault.', 'zgłosić problem、gwarancja、usterka、umówić technikaを使い、故障の内容と保証を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'repair', '["cefr:a2","scene:repair","grammar:past-and-relative","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Proszę opisać usterkę","Proszę opisać usterkę."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'repair', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l4-i05', 'sentence', 'Pralka zatrzymuje się podczas wirowania.', '洗濯機が脱水中に止まります。', 'The washing machine stops during spinning.', 'zgłosić problem、gwarancja、usterka、umówić technikaを使い、故障の内容と保証を説明します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'repair', '["cefr:a2","scene:repair","grammar:past-and-relative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Pralka zatrzymuje się podczas wirowania","Pralka zatrzymuje się podczas wirowania."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'repair', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l4-i06', 'sentence', 'Umówimy technika na najbliższy wolny termin.', '最も早い空き時間に技術者を手配します。', 'We will arrange a technician for the nearest available slot.', 'zgłosić problem、gwarancja、usterka、umówić technikaを使い、故障の内容と保証を説明します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'repair', '["cefr:a2","scene:repair","grammar:past-and-relative","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Umówimy technika na najbliższy wolny termin","Umówimy technika na najbliższy wolny termin."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'repair', 'neutral', 'male', 'partner', 'independent');
