INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u10-l5', 'a2-unit-10', 5, '近所の集まりを準備する', 'Spotkanie sąsiadów', 'organizować、przydałoby się、żeby、przygotowaćを使い、近所の役割分担を相談します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l5-i01', 'sentence', 'W sobotę organizujemy spotkanie dla sąsiadów.', '土曜日に近所の人の集まりを企画しています。', 'On Saturday we are organising a gathering for the neighbours.', 'organizować、przydałoby się、żeby、przygotowaćを使い、近所の役割分担を相談します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'community', '["cefr:a2","scene:community","grammar:conditional-and-dative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["W sobotę organizujemy spotkanie dla sąsiadów","W sobotę organizujemy spotkanie dla sąsiadów."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'community', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l5-i02', 'sentence', 'Czy potrzebują państwo pomocy?', '皆さんは助けが必要ですか？', 'Do you need any help?', 'organizować、przydałoby się、żeby、przygotowaćを使い、近所の役割分担を相談します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'community', '["cefr:a2","scene:community","grammar:conditional-and-dative","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Czy potrzebują państwo pomocy","Czy potrzebują państwo pomocy?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'community', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l5-i03', 'sentence', 'Przydałoby się, żeby ktoś przyniósł napoje.', '誰かが飲み物を持ってきてくれると助かります。', 'It would be useful if someone brought drinks.', 'organizować、przydałoby się、żeby、przygotowaćを使い、近所の役割分担を相談します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'community', '["cefr:a2","scene:community","grammar:conditional-and-dative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Przydałoby się, żeby ktoś przyniósł napoje","Przydałoby się, żeby ktoś przyniósł napoje."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'community', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l5-i04', 'sentence', 'Mogę kupić wodę i sok.', '水とジュースを買えます。', 'I can buy water and juice.', 'organizować、przydałoby się、żeby、przygotowaćを使い、近所の役割分担を相談します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'community', '["cefr:a2","scene:community","grammar:conditional-and-dative","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Mogę kupić wodę i sok","Mogę kupić wodę i sok."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'community', 'neutral', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l5-i05', 'sentence', 'Świetnie, a my przygotujemy jedzenie.', 'すばらしい、私たちは食べ物を準備します。', 'Great, and we will prepare the food.', 'organizować、przydałoby się、żeby、przygotowaćを使い、近所の役割分担を相談します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'community', '["cefr:a2","scene:community","grammar:conditional-and-dative","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Świetnie, a my przygotujemy jedzenie","Świetnie, a my przygotujemy jedzenie."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'community', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l5-i06', 'sentence', 'O której zaczynamy przygotowania?', '何時に準備を始めますか？', 'What time do we start preparing?', 'organizować、przydałoby się、żeby、przygotowaćを使い、近所の役割分担を相談します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'community', '["cefr:a2","scene:community","grammar:conditional-and-dative","register:neutral","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["O której zaczynamy przygotowania","O której zaczynamy przygotowania?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'community', 'neutral', 'male', 'partner', 'independent');
