INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u10-l5-s2', 'a2-u10-l5', 2, 'choice', 'a2-u10-l5-i01', '「W sobotę organizujemy spotkanie dla sąsiadów.」の意味を選びましょう。', 'organizować、przydałoby się、żeby、przygotowaćを使い、近所の役割分担を相談します。', '[{"value":"土曜日に近所の人の集まりを企画しています。","label":"土曜日に近所の人の集まりを企画しています。"},{"value":"誰かが飲み物を持ってきてくれると助かります。","label":"誰かが飲み物を持ってきてくれると助かります。"},{"value":"すばらしい、私たちは食べ物を準備します。","label":"すばらしい、私たちは食べ物を準備します。"},{"value":"何時に準備を始めますか？","label":"何時に準備を始めますか？"}]', 'multiple_choice', 'polish_to_meaning', '土曜日に近所の人の集まりを企画しています。', '', '', '', '[]', 0, '形から意味を認識する');
