INSERT OR IGNORE INTO pl_lessons (id, unit_id, lesson_number, title_ja, title_pl, description, estimated_minutes, status) VALUES ('a2-u10-l6', 'a2-unit-10', 6, 'A2の会話を振り返る', 'Potrafię rozmawiać', 'potrafić、najtrudniejsze było、powtórzyć i powiedzieć prościejを使い、会話方略と自己評価を言語化します。 代表的な相手の返答も含めて、短い往復を練習します。', 9, 'published');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l6-i01', 'sentence', 'Potrafię już załatwić prostą sprawę po polsku.', 'もうポーランド語で簡単な用事を済ませられます。', 'I can now handle a simple matter in Polish.', 'potrafić、najtrudniejsze było、powtórzyć i powiedzieć prościejを使い、会話方略と自己評価を言語化します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'integration', '["cefr:a2","scene:integration","grammar:reported-and-rephrase","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Potrafię już załatwić prostą sprawę po polsku","Potrafię już załatwić prostą sprawę po polsku."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'integration', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l6-i02', 'sentence', 'Co było dla pana najtrudniejsze?', '何が一番難しかったですか？', 'What was the most difficult thing for you?', 'potrafić、najtrudniejsze było、powtórzyć i powiedzieć prościejを使い、会話方略と自己評価を言語化します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'integration', '["cefr:a2","scene:integration","grammar:reported-and-rephrase","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Co było dla pana najtrudniejsze","Co było dla pana najtrudniejsze?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'integration', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l6-i03', 'sentence', 'Najtrudniejsze było zrozumienie szybkiej odpowiedzi.', '速い返答を理解するのが一番難しかったです。', 'Understanding a fast reply was the most difficult.', 'potrafić、najtrudniejsze było、powtórzyć i powiedzieć prościejを使い、会話方略と自己評価を言語化します。自分の発話として、男性話者の形を基準に練習する。 レジスターはneutral、教材内の学習者は男性話者を想定する。', 'integration', '["cefr:a2","scene:integration","grammar:reported-and-rephrase","register:neutral","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Najtrudniejsze było zrozumienie szybkiej odpowiedzi","Najtrudniejsze było zrozumienie szybkiej odpowiedzi."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'integration', 'neutral', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l6-i04', 'sentence', 'Jak poprosił pan o wyjaśnienie?', 'どうやって説明を求めましたか？', 'How did you ask for an explanation?', 'potrafić、najtrudniejsze było、powtórzyć i powiedzieć prościejを使い、会話方略と自己評価を言語化します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'integration', '["cefr:a2","scene:integration","grammar:reported-and-rephrase","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["Jak poprosił pan o wyjaśnienie","Jak poprosił pan o wyjaśnienie?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'integration', 'formal', 'male', 'partner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l6-i05', 'sentence', 'Powiedziałem: Czy może pan powtórzyć i powiedzieć to prościej?', '「もう一度言って、もっと簡単に言えますか」と言いました。', 'I said: Could you repeat and say it more simply?', 'potrafić、najtrudniejsze było、powtórzyć i powiedzieć prościejを使い、会話方略と自己評価を言語化します。自分の発話として、男性話者の形を基準に練習する。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'integration', '["cefr:a2","scene:integration","grammar:reported-and-rephrase","register:formal","role:learner","speaker:male","skill:spoken_production","skill:spoken_interaction"]', '["Powiedziałem: Czy może pan powtórzyć i powiedzieć to prościej","Powiedziałem: Czy może pan powtórzyć i powiedzieć to prościej?"]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["spoken_production","spoken_interaction"]', 'integration', 'formal', 'male', 'learner', 'independent');
INSERT OR IGNORE INTO pl_learning_items (id, type, polish, meaning_ja, meaning_en, grammar_note, topic, tags_json, accepted_answers_json, content_version, status, created_at, cefr_level, skills_json, scene, register, speaker_gender, dialogue_role, source_kind) VALUES ('a2-u10-l6-i06', 'sentence', 'To ważna umiejętność, proszę używać jej także poza lekcją.', 'それは大切な技能です、授業以外でも使ってください。', 'That is an important skill; please use it outside the lesson too.', 'potrafić、najtrudniejsze było、powtórzyć i powiedzieć prościejを使い、会話方略と自己評価を言語化します。相手の典型的な質問・返答として聞き取り、必要なら言い換えを求める。 レジスターはformal、教材内の学習者は男性話者を想定する。', 'integration', '["cefr:a2","scene:integration","grammar:reported-and-rephrase","register:formal","role:partner","speaker:male","skill:listening","skill:spoken_interaction"]', '["To ważna umiejętność, proszę używać jej także poza lekcją","To ważna umiejętność, proszę używać jej także poza lekcją."]', 'a1-a2-2026.1', 'published', strftime('%Y-%m-%dT%H:%M:%fZ','now'), 'A2', '["listening","spoken_interaction"]', 'integration', 'formal', 'male', 'partner', 'independent');
