INSERT OR IGNORE INTO pl_lesson_steps (id, lesson_id, step_number, kind, item_id, prompt_ja, explanation, options_json, question_type, direction, answer_text, cloze_prefix, cloze_suffix, cloze_answer, tokens_json, scaffold_level, hint_text) VALUES ('a2-u10-l6-s2', 'a2-u10-l6', 2, 'choice', 'a2-u10-l6-i01', '「Potrafię już załatwić prostą sprawę po polsku.」の意味を選びましょう。', 'potrafić、najtrudniejsze było、powtórzyć i powiedzieć prościejを使い、会話方略と自己評価を言語化します。', '[{"value":"もうポーランド語で簡単な用事を済ませられます。","label":"もうポーランド語で簡単な用事を済ませられます。"},{"value":"速い返答を理解するのが一番難しかったです。","label":"速い返答を理解するのが一番難しかったです。"},{"value":"「もう一度言って、もっと簡単に言えますか」と言いました。","label":"「もう一度言って、もっと簡単に言えますか」と言いました。"},{"value":"それは大切な技能です、授業以外でも使ってください。","label":"それは大切な技能です、授業以外でも使ってください。"}]', 'multiple_choice', 'polish_to_meaning', 'もうポーランド語で簡単な用事を済ませられます。', '', '', '', '[]', 0, '形から意味を認識する');
